/**
 * Handler for ContactTrigger.
 * Declared "without sharing" on purpose: the original trigger ran in system mode
 * (it could read and update any Account). This keeps that behaviour.
 */
public without sharing class ContactTriggerHandler {

    public static void run(System.TriggerOperation operation, List<Contact> newContacts) {
        switch on operation {
            when BEFORE_INSERT {
                applyAccountDefaults(newContacts, true);
            }
            when BEFORE_UPDATE {
                applyAccountDefaults(newContacts, false);
            }
            when AFTER_INSERT {
                copyPhoneToAccounts(newContacts);
            }
            when else {
                // no logic for other contexts
            }
        }
    }

    /**
     * Before insert/update: default MailingCountry from Account.BillingCountry.
     * On insert only, also default LeadSource from Account.AccountSource.
     * Uses one SOQL query.
     */
    @TestVisible
    private static void applyAccountDefaults(List<Contact> contacts, Boolean isInsert) {
        Set<Id> accountIds = collectAccountIds(contacts, false);
        if (accountIds.isEmpty()) {
            return;
        }

        Map<Id, Account> accountsById = new Map<Id, Account>(
            [SELECT Id, BillingCountry, AccountSource FROM Account WHERE Id IN :accountIds]
        );

        for (Contact c : contacts) {
            if (c.AccountId == null) {
                continue;
            }
            Account a = accountsById.get(c.AccountId);
            if (a == null) {
                continue;
            }
            if (String.isBlank(c.MailingCountry)) {
                c.MailingCountry = a.BillingCountry;
            }
            if (isInsert && String.isBlank(c.LeadSource)) {
                c.LeadSource = a.AccountSource;
            }
        }
    }

    /**
     * After insert: if a new contact has a phone and its account has none,
     * copy the contact's phone to the account.
     * The first contact in trigger order wins for each account, as before.
     * Uses one SOQL query and at most one DML statement.
     */
    @TestVisible
    private static void copyPhoneToAccounts(List<Contact> contacts) {
        Set<Id> accountIds = collectAccountIds(contacts, true);
        if (accountIds.isEmpty()) {
            return;
        }

        Map<Id, Account> accountsById = new Map<Id, Account>(
            [SELECT Id, Phone FROM Account WHERE Id IN :accountIds]
        );

        Map<Id, Account> accountsToUpdate = new Map<Id, Account>();
        for (Contact c : contacts) {
            if (c.AccountId == null || String.isBlank(c.Phone)) {
                continue;
            }
            Account a = accountsById.get(c.AccountId);
            if (a == null) {
                continue;
            }
            // Mutating the in-memory record means later contacts of the same
            // account see the phone as already set, so the first one wins.
            if (String.isBlank(a.Phone)) {
                a.Phone = c.Phone;
                accountsToUpdate.put(a.Id, a);
            }
        }

        if (!accountsToUpdate.isEmpty()) {
            update accountsToUpdate.values();
        }
    }

    private static Set<Id> collectAccountIds(List<Contact> contacts, Boolean requirePhone) {
        Set<Id> accountIds = new Set<Id>();
        for (Contact c : contacts) {
            if (c.AccountId == null) {
                continue;
            }
            if (requirePhone && String.isBlank(c.Phone)) {
                continue;
            }
            accountIds.add(c.AccountId);
        }
        return accountIds;
    }
}
