/**
 * Client for the FX rate provider exposed through the Named Credential FB_Exchange_Rates.
 * The Named Credential supplies the base URL and the authentication.
 */
public with sharing class ExchangeRateClient {

    public class ExchangeRateException extends Exception {}

    @TestVisible
    private static final String ENDPOINT = 'callout:FB_Exchange_Rates/v1/latest';
    private static final Pattern CURRENCY_PATTERN = Pattern.compile('^[A-Z]{3}$');
    private static final Integer TIMEOUT_MS = 20000;

    /**
     * Returns the latest rates for the requested quote currencies against the base currency.
     * The keys of the returned map are the normalised (trimmed, upper-cased) quote codes.
     */
    public static Map<String, Decimal> getRates(String baseCurrency, Set<String> quoteCurrencies) {
        String base = normalise(baseCurrency);

        if (quoteCurrencies == null || quoteCurrencies.isEmpty()) {
            throw new ExchangeRateException('At least one quote currency is required.');
        }
        Set<String> quotes = new Set<String>();
        for (String q : quoteCurrencies) {
            quotes.add(normalise(q));
        }

        // Only A-Z codes reach this point, so no further URL encoding is needed.
        List<String> quoteList = new List<String>(quotes);
        quoteList.sort();

        HttpRequest req = new HttpRequest();
        req.setEndpoint(ENDPOINT + '?base=' + base + '&symbols=' + String.join(quoteList, ','));
        req.setMethod('GET');
        req.setHeader('Accept', 'application/json');
        req.setTimeout(TIMEOUT_MS);

        HttpResponse res = send(req);
        if (res.getStatusCode() == 503) {
            // Retry once with an identical request.
            res = send(req);
        }

        Integer status = res.getStatusCode();
        if (status != 200) {
            throw new ExchangeRateException(
                'Exchange rate request failed with HTTP status ' + status + '.');
        }

        Map<String, Object> rates = parseRates(res.getBody());

        Map<String, Decimal> result = new Map<String, Decimal>();
        for (String q : quoteList) {
            if (!rates.containsKey(q) || rates.get(q) == null) {
                throw new ExchangeRateException('No rate returned for currency ' + q + '.');
            }
            result.put(q, toDecimal(rates.get(q), q));
        }
        return result;
    }

    private static String normalise(String code) {
        if (code == null) {
            throw new ExchangeRateException('Currency code must not be null.');
        }
        String normalised = code.trim().toUpperCase();
        if (!CURRENCY_PATTERN.matcher(normalised).matches()) {
            throw new ExchangeRateException('Invalid currency code: ' + code);
        }
        return normalised;
    }

    private static HttpResponse send(HttpRequest req) {
        try {
            return new Http().send(req);
        } catch (CalloutException e) {
            throw new ExchangeRateException('Exchange rate callout failed: ' + e.getMessage());
        }
    }

    private static Map<String, Object> parseRates(String body) {
        if (String.isBlank(body)) {
            throw new ExchangeRateException('Exchange rate response body is empty.');
        }
        Object parsed;
        try {
            parsed = JSON.deserializeUntyped(body);
        } catch (Exception e) {
            throw new ExchangeRateException('Could not parse exchange rate response: ' + e.getMessage());
        }
        if (!(parsed instanceof Map<String, Object>)) {
            throw new ExchangeRateException('Unexpected exchange rate response format.');
        }
        Object ratesObj = ((Map<String, Object>) parsed).get('rates');
        if (!(ratesObj instanceof Map<String, Object>)) {
            throw new ExchangeRateException('Exchange rate response contains no rates.');
        }
        return (Map<String, Object>) ratesObj;
    }

    private static Decimal toDecimal(Object value, String code) {
        if (value instanceof Decimal) {
            return (Decimal) value;
        } else if (value instanceof Integer) {
            return Decimal.valueOf((Integer) value);
        } else if (value instanceof Long) {
            return Decimal.valueOf((Long) value);
        } else if (value instanceof Double) {
            return Decimal.valueOf((Double) value);
        } else if (value instanceof String) {
            try {
                return Decimal.valueOf((String) value);
            } catch (Exception e) {
                // fall through
            }
        }
        throw new ExchangeRateException('Invalid rate value for currency ' + code + '.');
    }
}
