/**
 * Parses free-text supplier payment terms into net days and due dates.
 */
public with sharing class PaymentTerms {

    @TestVisible
    private static final Integer MAX_NET_DAYS = 180;

    private static final Pattern NET_PATTERN =
        Pattern.compile('(?i)^NET\\s*(\\d{1,3})$');

    private static final Pattern DUE_ON_RECEIPT_PATTERN =
        Pattern.compile('(?i)^DUE\\s+ON\\s+RECEIPT$');

    /**
     * Returns the number of net days represented by the given terms.
     * @throws UnsupportedTermsException if the terms are null, blank or unrecognised
     * @throws TermsOutOfRangeException if the number of days exceeds 180
     */
    public static Integer parseNetDays(String terms) {
        if (String.isBlank(terms)) {
            throw unsupported(terms);
        }

        String normalized = terms.trim();

        if (DUE_ON_RECEIPT_PATTERN.matcher(normalized).matches()) {
            return 0;
        }

        Matcher m = NET_PATTERN.matcher(normalized);
        if (m.matches()) {
            Integer days = Integer.valueOf(m.group(1));
            if (days > MAX_NET_DAYS) {
                throw new TermsOutOfRangeException('Net days out of range: ' + days);
            }
            return days;
        }

        throw unsupported(terms);
    }

    /**
     * Returns invoiceDate plus the net days represented by the given terms.
     * @throws UnsupportedTermsException if the terms are null, blank or unrecognised
     * @throws TermsOutOfRangeException if the number of days exceeds 180
     * @throws IllegalArgumentException if invoiceDate is null (terms are validated first)
     */
    public static Date dueDate(Date invoiceDate, String terms) {
        Integer days = parseNetDays(terms);
        if (invoiceDate == null) {
            throw new IllegalArgumentException('Invoice date is required to calculate a due date.');
        }
        return invoiceDate.addDays(days);
    }

    private static UnsupportedTermsException unsupported(String terms) {
        // String concatenation renders a null input as 'null', as required.
        return new UnsupportedTermsException('Unsupported payment terms: ' + terms);
    }
}
