/**
 * Generic record search service used by the admin "record finder" Lightning component.
 *
 * Security:
 *  - Object and field names are never concatenated from raw input. Each name is checked
 *    against the object's schema and the canonical API name from describe is used.
 *  - Filter values are never concatenated into the query. They are passed as bind
 *    variables through Database.queryWithBinds.
 *  - The query runs in USER_MODE, so record sharing, object permissions and field-level
 *    security of the running user are enforced. Object and field access is also
 *    pre-checked so the caller gets a SearchException.
 */
public with sharing class RecordSearchService {

    public class SearchException extends Exception {}

    private static final Integer MIN_ROWS = 1;
    private static final Integer MAX_ROWS = 200;

    public static List<SObject> search(
        String objectApiName,
        List<String> fields,
        Map<String, Object> filters,
        String orderByField,
        Integer maxRows
    ) {
        Schema.DescribeSObjectResult objDescribe = describeObject(objectApiName);
        String objectName = objDescribe.getName();

        if (!objDescribe.isAccessible() || !objDescribe.isQueryable()) {
            throw new SearchException('You do not have access to object ' + objectName + '.');
        }

        if (fields == null || fields.isEmpty()) {
            throw new SearchException('At least one field must be requested.');
        }

        if (maxRows == null || maxRows < MIN_ROWS || maxRows > MAX_ROWS) {
            throw new SearchException(
                'maxRows must be between ' + MIN_ROWS + ' and ' + MAX_ROWS + '.'
            );
        }

        Map<String, Schema.SObjectField> fieldMap = objDescribe.fields.getMap();

        // SELECT list: Id plus the requested fields, de-duplicated case-insensitively
        List<String> selectList = new List<String>{ 'Id' };
        Set<String> selectedLower = new Set<String>{ 'id' };
        for (String requested : fields) {
            Schema.DescribeFieldResult fd = resolveField(fieldMap, requested, objectName);
            String canonical = fd.getName();
            if (selectedLower.add(canonical.toLowerCase())) {
                selectList.add(canonical);
            }
        }

        // WHERE clause with bind variables
        List<String> conditions = new List<String>();
        Map<String, Object> binds = new Map<String, Object>();
        if (filters != null && !filters.isEmpty()) {
            Integer idx = 0;
            for (String key : filters.keySet()) {
                Schema.DescribeFieldResult fd = resolveField(fieldMap, key, objectName);
                if (!fd.isFilterable()) {
                    throw new SearchException(
                        'Field ' + fd.getName() + ' cannot be used in a filter.'
                    );
                }
                Object value = filters.get(key);
                if (value == null) {
                    conditions.add(fd.getName() + ' = null');
                } else {
                    String bindName = 'p' + idx;
                    idx++;
                    binds.put(bindName, value);
                    conditions.add(fd.getName() + ' = :' + bindName);
                }
            }
        }

        // ORDER BY
        String orderByClause = '';
        if (String.isNotBlank(orderByField)) {
            Schema.DescribeFieldResult fd = resolveField(fieldMap, orderByField, objectName);
            if (!fd.isSortable()) {
                throw new SearchException('Field ' + fd.getName() + ' cannot be sorted.');
            }
            orderByClause = ' ORDER BY ' + fd.getName() + ' ASC';
        }

        String soql = 'SELECT ' + String.join(selectList, ', ') + ' FROM ' + objectName;
        if (!conditions.isEmpty()) {
            soql += ' WHERE ' + String.join(conditions, ' AND ');
        }
        soql += orderByClause;
        soql += ' LIMIT ' + String.valueOf(maxRows);

        try {
            return Database.queryWithBinds(soql, binds, AccessLevel.USER_MODE);
        } catch (Exception e) {
            // Covers type mismatches between filter values and field types,
            // access errors raised by USER_MODE and any other query failure.
            throw new SearchException('Search failed: ' + e.getMessage());
        }
    }

    private static Schema.DescribeSObjectResult describeObject(String objectApiName) {
        if (String.isBlank(objectApiName)) {
            throw new SearchException('An object API name is required.');
        }
        Schema.SObjectType sType;
        try {
            // Global describe map keys are case-insensitive
            sType = Schema.getGlobalDescribe().get(objectApiName.trim());
        } catch (Exception e) {
            sType = null;
        }
        if (sType == null) {
            throw new SearchException('Object ' + objectApiName + ' does not exist.');
        }
        return sType.getDescribe();
    }

    private static Schema.DescribeFieldResult resolveField(
        Map<String, Schema.SObjectField> fieldMap,
        String fieldName,
        String objectName
    ) {
        if (String.isBlank(fieldName)) {
            throw new SearchException('A blank field name was supplied for ' + objectName + '.');
        }
        // Field map keys are case-insensitive
        Schema.SObjectField token = fieldMap.get(fieldName.trim());
        if (token == null) {
            throw new SearchException(
                'Field ' + fieldName + ' is not a field of ' + objectName + '.'
            );
        }
        Schema.DescribeFieldResult fd = token.getDescribe();
        if (!fd.isAccessible()) {
            throw new SearchException(
                'You do not have access to field ' + fd.getName() + ' on ' + objectName + '.'
            );
        }
        return fd;
    }
}
```

Behaviour that goes beyond the spec:

- **Null filter values:** a null value becomes `field = null`, which matches records where the field is empty. It is written as a literal instead of a bind.
- **Duplicate fields:** if a field is requested twice, or `Id` is requested, it appears in the `SELECT` list only once. SOQL rejects duplicate fields.
- **Wrong value types:** if a value doesn't match the field's type (for example, a String for a Date field), the query fails. That error is turned into `SearchException` rather than leaking a `QueryException`.

The action runs one bulk query per batch of Flow requests. It enforces the running user's sharing, field-level security and object permissions.

