/**
 * Invocable action for Flow: finds an existing Contact by email address.
 * Bulk-safe (one SOQL query per invocation) and respects the running user's
 * sharing, object permissions and field-level security.
 */
public with sharing class ContactLookupAction {

    public class Request {
        @InvocableVariable(
            label='Email'
            description='Email address of the contact to find. Case and leading/trailing spaces are ignored.'
            required=true
        )
        public String email;
    }

    public class Result {
        @InvocableVariable(
            label='Contact Id'
            description='Id of the matching contact (earliest created if several match); null if none found.'
        )
        public Id contactId;

        @InvocableVariable(
            label='Found'
            description='True if a matching contact was found.'
        )
        public Boolean found;

        public Result(Id contactId) {
            this.contactId = contactId;
            this.found = (contactId != null);
        }
    }

    @InvocableMethod(
        label='Find Contact by Email'
        description='Finds an existing contact by email (case-insensitive, trimmed). Returns the earliest created contact if several match.'
        category='Contact'
    )
    public static List<Result> find(List<Request> requests) {
        List<Result> results = new List<Result>();
        if (requests == null || requests.isEmpty()) {
            return results;
        }

        // Collect normalized emails from all requests.
        Set<String> normalizedEmails = new Set<String>();
        for (Request req : requests) {
            String key = normalize(req == null ? null : req.email);
            if (key != null) {
                normalizedEmails.add(key);
            }
        }

        // Single query for the whole batch. SOQL Email comparison is case-insensitive.
        // Ordering by CreatedDate (then Id as a deterministic tie-breaker) means the
        // first contact seen per email is the earliest created.
        Map<String, Id> contactIdByEmail = new Map<String, Id>();
        if (!normalizedEmails.isEmpty()) {
            for (Contact c : [
                SELECT Id, Email
                FROM Contact
                WHERE Email IN :normalizedEmails
                WITH USER_MODE
                ORDER BY CreatedDate ASC, Id ASC
            ]) {
                String key = normalize(c.Email);
                if (key != null && !contactIdByEmail.containsKey(key)) {
                    contactIdByEmail.put(key, c.Id);
                }
            }
        }

        // Exactly one result per request, in the same order.
        for (Request req : requests) {
            String key = normalize(req == null ? null : req.email);
            Id matchId = (key == null) ? null : contactIdByEmail.get(key);
            results.add(new Result(matchId));
        }
        return results;
    }

    /**
     * Trims and lower-cases an email; returns null for blank/null input.
     */
    private static String normalize(String email) {
        if (String.isBlank(email)) {
            return null;
        }
        return email.trim().toLowerCase();
    }
}
```

**Design notes**
- **Bulk handling:** all non-blank emails are collected first. The class then runs a single `Email IN :set` query, or no query if every email is blank. Results are built afterwards by looking each request up in a map, so they come back in request order.
- **Normalizing emails:** each email is trimmed and lower-cased, both in the query input and when building the map key. SOQL email comparison is already case-insensitive, and this keeps the map lookup consistent with it.
- **Duplicate emails:** the query sorts by `ORDER BY CreatedDate ASC, Id ASC`, and only the first contact per email is kept. That gives the earliest created contact, with `Id` breaking ties between contacts created at the same time.
- **Blank, null or unmatched email:** these return `found = false` and `contactId = null`.
- **Security:** the class is declared `with sharing`, and the query uses `WITH USER_MODE`. That also enforces object and field permissions. If a user can't read Contact or the Email field, the query fails rather than quietly returning nothing.

