/**
 * Parses order JSON payloads posted by the e-commerce platform and builds
 * acknowledgement responses.
 *
 * The parser reads the payload with JSON.deserializeUntyped. This avoids
 * problems with the Apex reserved words "number", "date" and "currency", and
 * lets us check every value's type ourselves.
 *
 * Every failure, including unexpected runtime errors, is reported as an
 * OrderPayloadParser.PayloadException.
 */
public with sharing class OrderPayloadParser {

    public class PayloadException extends Exception {}

    public class Order {
        public String orderNumber;
        public Date orderDate;
        public String currencyCode;
        public String customerEmail;
        public List<Line> lines = new List<Line>();
        public Decimal total = 0;
    }

    public class Line {
        public String sku;
        public Integer quantity;
        public Decimal unitPrice;
        public Decimal discount = 0;
        public Decimal lineTotal;
    }

    private static final Pattern ISO_DATE = Pattern.compile('^(\\d{4})-(\\d{2})-(\\d{2})$');

    // ------------------------------------------------------------------ parse

    public static Order parse(String body) {
        if (String.isBlank(body)) {
            throw new PayloadException('Request body is empty.');
        }

        Object root;
        try {
            root = JSON.deserializeUntyped(body);
        } catch (Exception e) {
            throw new PayloadException('Request body is not valid JSON: ' + e.getMessage());
        }

        if (!(root instanceof Map<String, Object>)) {
            throw new PayloadException('Request body must be a JSON object.');
        }

        try {
            return buildOrder((Map<String, Object>) root);
        } catch (PayloadException pe) {
            throw pe;
        } catch (Exception e) {
            throw new PayloadException('Invalid order payload: ' + e.getMessage());
        }
    }

    private static Order buildOrder(Map<String, Object> data) {
        Order ord = new Order();

        String orderNumber = asString(data.get('number'), 'number');
        if (String.isBlank(orderNumber)) {
            throw new PayloadException('Order "number" is required.');
        }
        ord.orderNumber = orderNumber;

        ord.orderDate = parseIsoDate(data.get('date'));
        ord.currencyCode = asString(data.get('currency'), 'currency');

        Object customerObj = data.get('customer');
        if (customerObj != null) {
            if (!(customerObj instanceof Map<String, Object>)) {
                throw new PayloadException('"customer" must be a JSON object.');
            }
            Map<String, Object> customer = (Map<String, Object>) customerObj;
            ord.customerEmail = asString(customer.get('email'), 'customer.email');
        }

        Object linesObj = data.get('lines');
        Decimal total = 0;
        if (linesObj != null) {
            if (!(linesObj instanceof List<Object>)) {
                throw new PayloadException('"lines" must be a JSON array.');
            }
            Integer index = 0;
            for (Object lineObj : (List<Object>) linesObj) {
                Line ln = buildLine(lineObj, index);
                ord.lines.add(ln);
                total += ln.lineTotal;
                index++;
            }
        }
        ord.total = total.setScale(2, RoundingMode.HALF_UP);
        return ord;
    }

    private static Line buildLine(Object lineObj, Integer index) {
        String prefix = 'lines[' + index + ']';
        if (!(lineObj instanceof Map<String, Object>)) {
            throw new PayloadException(prefix + ' must be a JSON object.');
        }
        Map<String, Object> data = (Map<String, Object>) lineObj;
        Line ln = new Line();

        String sku = asString(data.get('sku'), prefix + '.sku');
        if (String.isBlank(sku)) {
            throw new PayloadException(prefix + '.sku is required.');
        }
        ln.sku = sku;

        Decimal qty = asDecimal(data.get('quantity'), prefix + '.quantity');
        if (qty == null) {
            throw new PayloadException(prefix + '.quantity is required.');
        }
        if (qty <= 0) {
            throw new PayloadException(prefix + '.quantity must be positive.');
        }
        if (qty != qty.round(System.RoundingMode.DOWN) || qty > 2147483647) {
            throw new PayloadException(prefix + '.quantity must be a whole number within range.');
        }
        ln.quantity = qty.intValue();

        Decimal price = asDecimal(data.get('unitPrice'), prefix + '.unitPrice');
        if (price == null) {
            throw new PayloadException(prefix + '.unitPrice is required.');
        }
        if (price < 0) {
            throw new PayloadException(prefix + '.unitPrice must not be negative.');
        }
        ln.unitPrice = price;

        Decimal discount = asDecimal(data.get('discount'), prefix + '.discount');
        if (discount == null) {
            discount = 0;
        }
        if (discount < 0 || discount > 1) {
            throw new PayloadException(prefix + '.discount must be between 0 and 1.');
        }
        ln.discount = discount;

        Decimal raw = Decimal.valueOf(ln.quantity) * price * (1 - discount);
        ln.lineTotal = raw.setScale(2, RoundingMode.HALF_UP);
        return ln;
    }

    // ---------------------------------------------------------------- helpers

    private static String asString(Object value, String field) {
        if (value == null) {
            return null;
        }
        if (value instanceof String) {
            return (String) value;
        }
        if (value instanceof Map<String, Object> || value instanceof List<Object>) {
            throw new PayloadException('"' + field + '" must be a scalar value.');
        }
        // Accept numbers or booleans by converting them to text.
        return String.valueOf(value);
    }

    private static Decimal asDecimal(Object value, String field) {
        if (value == null) {
            return null;
        }
        if (value instanceof Integer || value instanceof Long
                || value instanceof Decimal || value instanceof Double) {
            try {
                if (value instanceof Double) {
                    return Decimal.valueOf((Double) value);
                }
                return Decimal.valueOf(String.valueOf(value));
            } catch (Exception e) {
                throw new PayloadException('"' + field + '" is not a valid number.');
            }
        }
        throw new PayloadException('"' + field + '" must be a JSON number.');
    }

    private static Date parseIsoDate(Object value) {
        if (value == null) {
            return null;
        }
        if (!(value instanceof String)) {
            throw new PayloadException('"date" must be a string in yyyy-MM-dd format.');
        }
        String s = ((String) value).trim();
        if (s.length() == 0) {
            return null;
        }
        Matcher m = ISO_DATE.matcher(s);
        if (!m.matches()) {
            throw new PayloadException('"date" must be in yyyy-MM-dd format.');
        }
        Integer y = Integer.valueOf(m.group(1));
        Integer mo = Integer.valueOf(m.group(2));
        Integer d = Integer.valueOf(m.group(3));
        if (y < 1 || mo < 1 || mo > 12 || d < 1 || d > Date.daysInMonth(y, mo)) {
            throw new PayloadException('"date" is not a valid calendar date.');
        }
        return Date.newInstance(y, mo, d);
    }

    // ------------------------------------------------------- acknowledgement

    public static String toAcknowledgement(Order order) {
        if (order == null) {
            throw new PayloadException('Order is required to build an acknowledgement.');
        }
        Integer lineCount = order.lines == null ? 0 : order.lines.size();
        Decimal total = order.total == null ? 0 : order.total;

        JSONGenerator gen = JSON.createGenerator(false);
        gen.writeStartObject();
        if (order.orderNumber == null) {
            gen.writeNullField('number');
        } else {
            gen.writeStringField('number', order.orderNumber);
        }
        gen.writeStringField('status', 'RECEIVED');
        gen.writeNumberField('lineCount', lineCount);
        gen.writeNumberField('total', total);
        gen.writeEndObject();
        return gen.getAsString();
    }
}
```

**Notes**

- **Numbers:** Arithmetic uses `Decimal`, so `1.005` rounds to `1.01` with `RoundingMode.HALF_UP`. The `total` is the sum of the rounded line totals.
- **Unknown properties** anywhere in the payload are ignored.
- **One exception type:** Any unexpected runtime error inside `parse` is caught and rethrown as `PayloadException`.
- **Rejections beyond your list:** These all throw `PayloadException`, because I judged each to be clearly bad data:
  - an invalid `date` string;
  - a `quantity` that is not a whole number;
  - a `discount` outside 0–1;
  - a non-numeric numeric field;
  - `lines` that is not an array.
- **Blank SKU:** A blank `sku` is treated the same as a missing one and is rejected.

