/**
 * Maintains Account.FB_Open_Pipeline__c (sum of Amount of open opportunities, blank = 0)
 * and Account.FB_Open_Opportunities__c (count of open opportunities).
 *
 * Design notes:
 * - Totals are always recomputed from the database (aggregate query), never incremented,
 *   so they stay correct across repeated DML on the same records in one transaction.
 * - No static "already ran" flag (that would break multiple DML statements per transaction).
 *   Recursion with the legacy AccountTrigger (which updates open opportunities on every
 *   account update) is avoided because:
 *     a) on update, only changes to AccountId, Amount or IsClosed are relevant, and the
 *        legacy trigger changes none of these;
 *     b) accounts are only updated when their stored totals actually differ.
 * - Runs without sharing: like a roll-up summary, the totals must include all opportunities
 *   and must be writable regardless of the running user's access to the account.
 */
public without sharing class OpportunityPipelineHandler {

    public static void handle(
        System.TriggerOperation operation,
        List<Opportunity> newList,
        Map<Id, Opportunity> oldMap
    ) {
        Set<Id> accountIds = new Set<Id>();

        switch on operation {
            when AFTER_INSERT, AFTER_UNDELETE {
                for (Opportunity opp : newList) {
                    addId(accountIds, opp.AccountId);
                }
            }
            when AFTER_UPDATE {
                for (Opportunity opp : newList) {
                    Opportunity oldOpp = oldMap.get(opp.Id);
                    if (opp.AccountId != oldOpp.AccountId
                            || opp.Amount != oldOpp.Amount
                            || opp.IsClosed != oldOpp.IsClosed) {
                        addId(accountIds, opp.AccountId);
                        addId(accountIds, oldOpp.AccountId);
                    }
                }
            }
            when AFTER_DELETE {
                for (Opportunity opp : oldMap.values()) {
                    addId(accountIds, opp.AccountId);
                }
            }
        }

        if (!accountIds.isEmpty()) {
            recalculate(accountIds);
        }
    }

    public static void recalculate(Set<Id> accountIds) {
        // Lock the accounts first so concurrent transactions cannot interleave
        // their recalculations and overwrite each other with stale totals.
        Map<Id, Account> accounts = new Map<Id, Account>([
            SELECT Id, FB_Open_Pipeline__c, FB_Open_Opportunities__c
            FROM Account
            WHERE Id IN :accountIds
            FOR UPDATE
        ]);
        if (accounts.isEmpty()) {
            return;
        }

        Map<Id, Decimal> pipelineByAccount = new Map<Id, Decimal>();
        Map<Id, Integer> countByAccount = new Map<Id, Integer>();
        for (AggregateResult ar : [
            SELECT AccountId accId, SUM(Amount) total, COUNT(Id) cnt
            FROM Opportunity
            WHERE AccountId IN :accounts.keySet() AND IsClosed = false
            GROUP BY AccountId
        ]) {
            Id accId = (Id) ar.get('accId');
            Decimal total = (Decimal) ar.get('total');
            pipelineByAccount.put(accId, total == null ? 0 : total);
            countByAccount.put(accId, (Integer) ar.get('cnt'));
        }

        List<Account> toUpdate = new List<Account>();
        for (Account acc : accounts.values()) {
            Decimal pipeline = pipelineByAccount.containsKey(acc.Id)
                ? pipelineByAccount.get(acc.Id) : 0;
            Integer openCount = countByAccount.containsKey(acc.Id)
                ? countByAccount.get(acc.Id) : 0;

            if (acc.FB_Open_Pipeline__c != pipeline
                    || acc.FB_Open_Opportunities__c != openCount) {
                toUpdate.add(new Account(
                    Id = acc.Id,
                    FB_Open_Pipeline__c = pipeline,
                    FB_Open_Opportunities__c = openCount
                ));
            }
        }

        if (!toUpdate.isEmpty()) {
            update toUpdate;
        }
    }

    private static void addId(Set<Id> ids, Id value) {
        if (value != null) {
            ids.add(value);
        }
    }
}
