/**
 * Purges old FB_Integration_Log__c records.
 *  - Non-ERROR logs (including blank Level__c) are deleted once created more than 30 days ago.
 *  - ERROR logs are kept until created more than 180 days ago.
 *
 * The scheduled run deletes up to SYNC_LIMIT records directly. If more qualifying
 * records remain, it hands the rest to a batch run of this same class, so large
 * volumes stay within governor limits.
 */
public with sharing class LogPurgeJob implements Schedulable, Database.Batchable<SObject> {

    public static final String JOB_NAME = 'Log purge (nightly)';
    public static final String NIGHTLY_CRON = '0 0 2 * * ?';

    @TestVisible
    private static final Integer SYNC_LIMIT = 5000;
    private static final Integer BATCH_SIZE = 2000;
    private static final Integer DEFAULT_RETENTION_DAYS = 30;
    private static final Integer ERROR_RETENTION_DAYS = 180;

    public LogPurgeJob() {
    }

    // ---------------------------------------------------------------- Scheduling

    public static Id scheduleNightly() {
        return System.schedule(JOB_NAME, NIGHTLY_CRON, new LogPurgeJob());
    }

    // ---------------------------------------------------------------- Schedulable

    public void execute(SchedulableContext ctx) {
        Datetime defaultCutoff = Datetime.now().addDays(-DEFAULT_RETENTION_DAYS);
        Datetime errorCutoff = Datetime.now().addDays(-ERROR_RETENTION_DAYS);

        List<FB_Integration_Log__c> logs = [
            SELECT Id
            FROM FB_Integration_Log__c
            WHERE CreatedDate < :defaultCutoff
              AND (Level__c = null OR Level__c != 'ERROR' OR CreatedDate < :errorCutoff)
            LIMIT :SYNC_LIMIT
        ];

        purge(logs);

        // More records may remain: hand off to batch processing.
        if (logs.size() == SYNC_LIMIT) {
            Database.executeBatch(new LogPurgeJob(), BATCH_SIZE);
        }
    }

    // ---------------------------------------------------------------- Batchable

    public Database.QueryLocator start(Database.BatchableContext bc) {
        Datetime defaultCutoff = Datetime.now().addDays(-DEFAULT_RETENTION_DAYS);
        Datetime errorCutoff = Datetime.now().addDays(-ERROR_RETENTION_DAYS);
        return Database.getQueryLocator([
            SELECT Id
            FROM FB_Integration_Log__c
            WHERE CreatedDate < :defaultCutoff
              AND (Level__c = null OR Level__c != 'ERROR' OR CreatedDate < :errorCutoff)
        ]);
    }

    public void execute(Database.BatchableContext bc, List<SObject> scope) {
        purge(scope);
    }

    public void finish(Database.BatchableContext bc) {
    }

    // ---------------------------------------------------------------- Helpers

    private static void purge(List<SObject> records) {
        if (records == null || records.isEmpty()) {
            return;
        }
        // Partial success: one locked or failed row must not block the whole purge.
        Database.DeleteResult[] results = Database.delete(records, false, AccessLevel.SYSTEM_MODE);
        for (Database.DeleteResult dr : results) {
            if (!dr.isSuccess()) {
                for (Database.Error err : dr.getErrors()) {
                    System.debug(LoggingLevel.WARN,
                        'LogPurgeJob could not delete ' + dr.getId() + ': ' + err.getMessage());
                }
            }
        }
    }
}
```

Assumptions and design notes:
- **Which logs are deleted:** logs created before now minus 30 days are deleted. ERROR logs are spared unless they are older than now minus 180 days.
- **Blank and odd-case levels:** blank `Level__c` is explicitly included in the delete. SOQL text comparison is case-insensitive, so `error` is also kept as ERROR.
- **Volume:** the scheduled run deletes up to 5,000 records directly. If it hits that limit, it starts a batch to delete the rest.
- **Failed rows:** deletes allow partial success, so one locked record does not stop the whole purge. Failures are written to the debug log.
- **Permissions:** the purge runs in system mode, so it works whatever access the user who scheduled it has.
- **Schedule:** `scheduleNightly()` uses the cron expression `0 0 2 * * ?` (every day at 02:00) and job name `Log purge (nightly)`.

