            Opportunity original = originals[i];
            Opportunity renewal = (Opportunity) renewals[i];

            Assert.isNull(renewal.Id, 'Renewal must be a new record');
            Assert.areEqual(original.Name + ' - Renewal', renewal.Name, 'Renewal name');
            Assert.areEqual(original.AccountId, renewal.AccountId, 'Renewal account');
