        Application.Domain.setMock(f.domainMock);
        return f;
    }

    private static void assertNothingAppliedOrCommitted(Fixture f) {
        ((IOpportunities) f.mocks.verify(f.domainMock, f.mocks.never()))
            .applyDiscount(fflib_Match.anyDecimal(), (fflib_ISObjectUnitOfWork) fflib_Match.anyObject());
        ((fflib_ISObjectUnitOfWork) f.mocks.verify(f.uowMock, f.mocks.never())).commitWork();
        ((fflib_ISObjectUnitOfWork) f.mocks.verify(f.uowMock, f.mocks.never()))
            .registerDirty((SObject) fflib_Match.anyObject());
