        mocks.startStubbing();
        // Required: SelectorFactory.setMock keys the mock by sObjectType().
        mocks.when(selectorMock.sObjectType()).thenReturn(Opportunity.SObjectType);
        if (expectedAccountIds != null) {
            mocks.when(selectorMock.selectOpenByAccountIds(expectedAccountIds)).thenReturn(returnedOpps);
