        Id accountId2 = fflib_IDGenerator.generate(Account.SObjectType);
        Set<Id> accountIds = new Set<Id>{ accountId1, accountId2 };

        List<Opportunity> opps = new List<Opportunity>{
            buildOpp(accountId1, 'Prospecting', 1000, 10),    // 100.00
            buildOpp(accountId2, 'Prospecting', 2000, 25),    // 500.00
            buildOpp(accountId1, 'Negotiation', 5000, 80),    // 4000.00
            buildOpp(accountId2, 'Qualification', 300, 50)    // 150.00
        };

