@IsTest
private class OpportunityCleanupServiceTest {
    private static final Date CUTOFF = Date.newInstance(2024, 6, 15);

    private static fflib_ApexMocks mocks;
    private static IOpportunitiesSelector selectorMock;
    private static fflib_ISObjectUnitOfWork uowMock;

    private static void setUpMocks(Set<Id> ids, List<Opportunity> selectorResult) {
        mocks = new fflib_ApexMocks();
        selectorMock = (IOpportunitiesSelector) mocks.mock(IOpportunitiesSelector.class);
        uowMock = (fflib_ISObjectUnitOfWork) mocks.mock(fflib_ISObjectUnitOfWork.class);

        mocks.startStubbing();
        mocks.when(selectorMock.sObjectType()).thenReturn(Opportunity.SObjectType);
        if (ids != null) {
            mocks.when(selectorMock.selectById(ids)).thenReturn(selectorResult);
        }
        mocks.stopStubbing();

        Application.Selector.setMock(selectorMock);
        Application.UnitOfWork.setMock(uowMock);
    }

    private static Opportunity newOpp(String stage, Date closeDate) {
        return new Opportunity(
            Id = fflib_IDGenerator.generate(Opportunity.SObjectType),
            Name = 'Opp ' + stage + ' ' + String.valueOf(closeDate),
            StageName = stage,
            CloseDate = closeDate,
            Description = 'original'
        );
    }

    private static Set<Id> idsOf(List<Opportunity> opps) {
        Set<Id> ids = new Set<Id>();
        for (Opportunity o : opps) {
            ids.add(o.Id);
        }
        return ids;
    }

    private static void verifyRegisteredAsLost(Id oppId) {
        ((fflib_ISObjectUnitOfWork) mocks.verify(uowMock, 1)).registerDirty(
            fflib_Match.sObjectWith(
                new Map<SObjectField, Object>{
                    Opportunity.Id => oppId,
                    Opportunity.StageName => 'Closed Lost',
                    Opportunity.Description => OpportunityCleanupService.LOST_REASON
                }
            )
        );
    }

    private static void verifyNeverRegistered(Id oppId) {
        ((fflib_ISObjectUnitOfWork) mocks.verify(uowMock, mocks.never())).registerDirty(
            fflib_Match.sObjectWith(new Map<SObjectField, Object>{ Opportunity.Id => oppId })
        );
    }

    @IsTest
    static void closeStale_closesOnlyOpenOpportunitiesBeforeCutoff() {
        Opportunity staleProspecting = newOpp('Prospecting', CUTOFF.addDays(-1));
        Opportunity staleNegotiation = newOpp('Negotiation/Review', CUTOFF.addDays(-30));
        Opportunity onCutoff = newOpp('Prospecting', CUTOFF);
        Opportunity afterCutoff = newOpp('Qualification', CUTOFF.addDays(1));
        Opportunity closedWon = newOpp('Closed Won', CUTOFF.addDays(-10));
        Opportunity closedLost = newOpp('Closed Lost', CUTOFF.addDays(-10));

        List<Opportunity> opps = new List<Opportunity>{
            staleProspecting, staleNegotiation, onCutoff, afterCutoff, closedWon, closedLost
        };
        Set<Id> ids = idsOf(opps);
        setUpMocks(ids, opps);

        Test.startTest();
        Integer result = OpportunityCleanupService.closeStale(ids, CUTOFF);
        Test.stopTest();

        Assert.areEqual(2, result, 'Should return the number of closed opportunities');

        // Stale ones registered with the expected values
        verifyRegisteredAsLost(staleProspecting.Id);
        verifyRegisteredAsLost(staleNegotiation.Id);

        // Exactly two registrations in total - nothing else registered
        ((fflib_ISObjectUnitOfWork) mocks.verify(uowMock, 2)).registerDirty(fflib_Match.anySObject());

        verifyNeverRegistered(onCutoff.Id);
        verifyNeverRegistered(afterCutoff.Id);
        verifyNeverRegistered(closedWon.Id);
        verifyNeverRegistered(closedLost.Id);

        // Commit exactly once
        ((fflib_ISObjectUnitOfWork) mocks.verify(uowMock, 1)).commitWork();

        // Non-stale records left untouched
        Assert.areEqual('Prospecting', onCutoff.StageName, 'Cutoff-day opportunity must be left alone');
        Assert.areEqual('original', onCutoff.Description, 'Cutoff-day opportunity must be left alone');
        Assert.areEqual('Qualification', afterCutoff.StageName, 'Future opportunity must be left alone');
        Assert.areEqual('original', afterCutoff.Description, 'Future opportunity must be left alone');
        Assert.areEqual('Closed Won', closedWon.StageName, 'Closed Won must be left alone');
        Assert.areEqual('original', closedWon.Description, 'Closed Won must be left alone');
        Assert.areEqual('original', closedLost.Description, 'Closed Lost must be left alone');
    }

    @IsTest
    static void closeStale_singleStaleOpportunity_commitsOnce() {
        Opportunity stale = newOpp('Prospecting', CUTOFF.addDays(-1));
        List<Opportunity> opps = new List<Opportunity>{ stale };
        Set<Id> ids = idsOf(opps);
        setUpMocks(ids, opps);

        Test.startTest();
        Integer result = OpportunityCleanupService.closeStale(ids, CUTOFF);
        Test.stopTest();

        Assert.areEqual(1, result, 'One opportunity should be closed');
        Assert.areEqual('Closed Lost', stale.StageName, 'Stage should be Closed Lost');
        Assert.areEqual(OpportunityCleanupService.LOST_REASON, stale.Description, 'Description should be the lost reason');
        verifyRegisteredAsLost(stale.Id);
        ((fflib_ISObjectUnitOfWork) mocks.verify(uowMock, 1)).registerDirty(fflib_Match.anySObject());
        ((fflib_ISObjectUnitOfWork) mocks.verify(uowMock, 1)).commitWork();
    }

    @IsTest
    static void closeStale_noStaleOpportunities_doesNotCommit() {
        Opportunity onCutoff = newOpp('Prospecting', CUTOFF);
        Opportunity afterCutoff = newOpp('Prospecting', CUTOFF.addDays(5));
        Opportunity closedWon = newOpp('Closed Won', CUTOFF.addDays(-5));
        Opportunity closedLost = newOpp('Closed Lost', CUTOFF.addDays(-5));
        List<Opportunity> opps = new List<Opportunity>{ onCutoff, afterCutoff, closedWon, closedLost };
        Set<Id> ids = idsOf(opps);
