/**
 * Central fflib Application factory configuration.
 * Tests may replace any implementation via the factories' setMock(...) methods.
 *
 * NOTE: static initialisers run in declaration order. Selector must be declared
 * before Domain because the DomainFactory is built from it.
 */
public inherited sharing class Application {
    // Unit of Work: parents are listed before children so that one commit can
    // insert Accounts, then Contacts and Opportunities of those Accounts, then
    // OpportunityContactRoles linking the new Opportunities and Contacts.
    public static final fflib_Application.UnitOfWorkFactory UnitOfWork = new fflib_Application.UnitOfWorkFactory(
        new List<Schema.SObjectType>{
            Account.SObjectType,
            Contact.SObjectType,
            Opportunity.SObjectType,
            OpportunityContactRole.SObjectType
        }
    );

    // Service: maps the interface to its implementation.
    public static final fflib_Application.ServiceFactory Service = new fflib_Application.ServiceFactory(
        new Map<Type, Type>{ IAccountsService.class => AccountsServiceImpl.class }
    );

    // Selector: maps each SObjectType to its selector class.
    public static final fflib_Application.SelectorFactory Selector = new fflib_Application.SelectorFactory(
        new Map<Schema.SObjectType, Type>{
            Account.SObjectType => AccountsSelector.class,
            Contact.SObjectType => ContactsSelector.class
        }
    );

    // Domain: uses the Selector factory above to query records for newInstance(Set<Id>).
    public static final fflib_Application.DomainFactory Domain = new fflib_Application.DomainFactory(
        Application.Selector,
        new Map<Schema.SObjectType, Type>{ Account.SObjectType => Accounts.Constructor.class }
    );
}
