    public Schema.SObjectType getSObjectType() {
        return Opportunity.SObjectType;
    }

    public List<Schema.SObjectField> getSObjectFieldList() {
        return new List<Schema.SObjectField>{
            Opportunity.Id,
            Opportunity.Name,
            Opportunity.AccountId,
            Opportunity.StageName,
            Opportunity.Amount,
            Opportunity.CloseDate
        };
    }

    public List<Opportunity> selectById(Set<Id> opportunityIds) {
        return (List<Opportunity>) selectSObjectsById(opportunityIds);
    }

    /**
     * Returns the open opportunities of the given accounts in this order:
     * highest Amount first, opportunities without an Amount last,
     * and equal amounts by earliest CloseDate.
     * At most maxRecords rows are returned. Each row includes Account.Name.
     */
    public List<Opportunity> selectTopOpenByAccountIds(Set<Id> accountIds, Integer maxRecords) {
        if (accountIds == null || accountIds.isEmpty() || maxRecords == null || maxRecords <= 0) {
            return new List<Opportunity>();
        }

        // Uses the selector's field list and its CRUD/FLS settings
        fflib_QueryFactory queryFactory = newQueryFactory();

        // Parent field; FLS is checked through the relationship when enforced
        queryFactory.selectField('Account.Name');

        queryFactory.setCondition('AccountId IN :accountIds AND IsClosed = false');

        // Replace the selector's default ordering (Name) for this query only
        queryFactory.setOrdering(Opportunity.Amount, fflib_QueryFactory.SortOrder.DESCENDING, true);
        queryFactory.addOrdering(Opportunity.CloseDate, fflib_QueryFactory.SortOrder.ASCENDING);
        // Deterministic tie-breaker
        queryFactory.addOrdering(Opportunity.Id, fflib_QueryFactory.SortOrder.ASCENDING);

        queryFactory.setLimit(maxRecords);

        return (List<Opportunity>) Database.query(queryFactory.toSOQL());
    }
}
```

Design notes:
- **Ordering:**
  - `setOrdering` removes the default `Name` ordering that `newQueryFactory()` adds, but only on this query factory. `selectById` and any other methods still sort by Name.
  - `Amount DESC` must be written with `NULLS LAST`. SOQL puts nulls first for descending sorts, so opportunities without an Amount would otherwise come first.
  - Equal amounts then sort by `CloseDate ASC` (earliest first). `Id` is added last only so the order is always the same.
- **Fields and security:** `newQueryFactory()` applies the selector's field list and its CRUD/FLS configuration. `Account.Name` is added with `selectField('Account.Name')`, which resolves the relationship and checks field access when FLS enforcement is on.
- **Sharing and limits:**
  - The class stays `inherited sharing`.
  - The method runs one query with `LIMIT maxRecords`.
  - If `accountIds` is null or empty, or `maxRecords` is null or not positive, it returns an empty list without querying.

