public with sharing class OpportunityWinService {

    private static final String CLOSED_WON = 'Closed Won';

    /**
     * Marks the given opportunities as Closed Won (skipping those already Closed Won),
     * and publishes one Deal_Won__e per closed opportunity only after the updates
     * have been committed successfully.
     *
     * @return number of opportunities closed by this call
     */
    public static Integer markWon(Set<Id> opportunityIds) {
        if (opportunityIds == null || opportunityIds.isEmpty()) {
            return 0;
        }

        Set<Id> ids = new Set<Id>(opportunityIds);
        ids.remove(null);
        if (ids.isEmpty()) {
            return 0;
        }

        List<Opportunity> opportunities = OpportunitiesSelector.newInstance().selectById(ids);

        fflib_ISObjectUnitOfWork uow = Application.UnitOfWork.newInstance();
        Date today = Date.today();
        Integer closedCount = 0;

        for (Opportunity opp : opportunities) {
            if (opp.StageName == CLOSED_WON) {
                continue;
            }

            // Only send the fields we intend to change
            uow.registerDirty(new Opportunity(
                Id = opp.Id,
                StageName = CLOSED_WON,
                CloseDate = today
            ));

            // Published by the unit of work only after commitWork() succeeds
            uow.registerPublishAfterSuccessTransaction(new Deal_Won__e(
                Opportunity_Id__c = String.valueOf(opp.Id),
                Amount__c = opp.Amount
            ));

            closedCount++;
        }

        if (closedCount == 0) {
            return 0;
        }

        // On failure the unit of work rolls back, does not publish the
        // after-success events and re-throws the exception to the caller.
        uow.commitWork();

        return closedCount;
    }
}
