```apex
/**
 * Matches in-memory Leads to in-memory Contacts by email address.
 *
 * Uses a map keyed by normalised email (O(leads + contacts)) instead of a
 * nested loop (O(leads * contacts)), which at 3,000 x 3,000 = 9M string
 * comparisons would risk the synchronous CPU time limit inside the import
 * transaction. Performs no SOQL and no DML.
 */
public with sharing class LeadContactMatcher {

    // Fixed locale so case-folding does not depend on the running user's locale.
    private static final String NORMALISE_LOCALE = 'en_US';

    /**
     * @param leads    leads to match (result has the same size and order)
     * @param contacts candidate contacts; on duplicate emails the first one wins
     * @return for each lead, the Id of the first contact with the same email
     *         (case-insensitive, trimmed), or null if none / blank email
     */
    public static List<Id> matchByEmail(List<Lead> leads, List<Contact> contacts) {
        List<Id> result = new List<Id>();
        if (leads == null || leads.isEmpty()) {
            return result;
        }

        Map<String, Id> contactIdByEmail = new Map<String, Id>();
        if (contacts != null) {
            for (Contact c : contacts) {
                if (c == null) {
                    continue;
                }
                String key = normalise(c.Email);
                // Keep the first contact in list order for a given email.
                if (key != null && !contactIdByEmail.containsKey(key)) {
                    contactIdByEmail.put(key, c.Id);
                }
            }
        }

        for (Lead l : leads) {
            String key = (l == null) ? null : normalise(l.Email);
            result.add(key == null ? null : contactIdByEmail.get(key));
        }
        return result;
    }

    /**
     * Trims and lower-cases an email; returns null for blank values so they never match.
     */
    private static String normalise(String email) {
        if (String.isBlank(email)) {
            return null;
        }
        return email.trim().toLowerCase(NORMALISE_LOCALE);
    }
}
