trigger CaseTrigger on Case (after update) {
    Set<Id> newlyClosedIds = new Set<Id>();

    for (Case c : Trigger.new) {
        Case oldCase = Trigger.oldMap.get(c.Id);
        Boolean justClosed = c.IsClosed && !oldCase.IsClosed;
        // Skip cases already handled earlier in this transaction (for example, a re-fire after a workflow field update)
        if (justClosed && c.ContactId != null && !CaseSurveyJob.alreadyQueued.contains(c.Id)) {
            newlyClosedIds.add(c.Id);
        }
    }

    if (newlyClosedIds.isEmpty()) {
        return;
    }

    CaseSurveyJob.alreadyQueued.addAll(newlyClosedIds);

    // Enqueue ONE job per trigger chunk (up to 200 cases), not one job per case.
    // A transaction can enqueue at most 50 jobs, or only 1 when already async.
    if (Limits.getQueueableJobs() < Limits.getLimitQueueableJobs()) {
        System.enqueueJob(new CaseSurveyJob(newlyClosedIds));
    } else {
        // No queueable capacity left in this transaction: create the tasks synchronously so no survey is lost
        CaseSurveyJob.createSurveyTasks(newlyClosedIds);
    }
}
