/**
 * Creates CSAT survey follow-up Tasks for closed Cases.
 * Runs asynchronously so a future vendor integration can be added here
 * (add Database.AllowsCallouts when callouts are introduced).
 */
public with sharing class CaseSurveyJob implements Queueable {

    // Transaction-scoped guard against queueing the same case twice
    public static Set<Id> alreadyQueued = new Set<Id>();

    private final Set<Id> caseIds;

    public CaseSurveyJob(Set<Id> caseIds) {
        this.caseIds = caseIds == null ? new Set<Id>() : new Set<Id>(caseIds);
    }

    // Convenience constructor for a single case
    public CaseSurveyJob(Id caseId) {
        this(new Set<Id>{ caseId });
    }

    public void execute(QueueableContext context) {
        createSurveyTasks(caseIds);
    }

    public static void createSurveyTasks(Set<Id> ids) {
        if (ids == null || ids.isEmpty()) {
            return;
        }

        List<Task> tasks = new List<Task>();
        Date dueDate = Date.today().addDays(2);

        // Re-check the state at run time: the case must still be closed and still have a contact
        for (Case c : [
            SELECT Id, CaseNumber, ContactId
            FROM Case
            WHERE Id IN :ids AND ContactId != null AND IsClosed = true
        ]) {
            tasks.add(new Task(
                WhatId = c.Id,
                WhoId = c.ContactId,
                Subject = 'CSAT survey: ' + c.CaseNumber,
                ActivityDate = dueDate,
                Status = 'Not Started'
            ));
        }

        if (tasks.isEmpty()) {
            return;
        }

        // Partial success: one bad record does not block the other cases' tasks
        Database.SaveResult[] results = Database.insert(tasks, false);
        for (Integer i = 0; i < results.size(); i++) {
            if (!results[i].isSuccess()) {
                for (Database.Error err : results[i].getErrors()) {
                    System.debug(LoggingLevel.ERROR,
                        'CSAT survey task failed for Case ' + tasks[i].WhatId + ': '
                        + err.getStatusCode() + ' - ' + err.getMessage());
                }
            }
        }
    }
}
