/**
 * Sends renewal reminder emails to the owners of the given opportunities.
 *
 * All messages are sent in a single Messaging.sendEmail call with allOrNothing = false.
 * Apex allows only 10 sendEmail invocations per transaction, so calling it once per
 * opportunity would hit an uncatchable LimitException with more than 10 records.
 * Partial-success mode gives the same per-email failure isolation within one call.
 */
public with sharing class RenewalReminderService {

    @TestVisible
    private static final String SUBJECT_PREFIX = 'Renewal due: ';

    /**
     * @param opportunityIds Ids of opportunities whose owners should be reminded (up to 200 per call).
     * @return number of emails that were sent successfully.
     */
    public static Integer sendReminders(List<Id> opportunityIds) {
        if (opportunityIds == null || opportunityIds.isEmpty()) {
            return 0;
        }

        Set<Id> uniqueIds = new Set<Id>(opportunityIds);
        uniqueIds.remove(null);
        if (uniqueIds.isEmpty()) {
            return 0;
        }

        // Inactive users cannot receive email, so skip them up front.
        List<Opportunity> opportunities = [
            SELECT Id, Name, CloseDate, OwnerId
            FROM Opportunity
            WHERE Id IN :uniqueIds
              AND Owner.IsActive = true
        ];

        List<Messaging.SingleEmailMessage> messages = new List<Messaging.SingleEmailMessage>();
        for (Opportunity opp : opportunities) {
            messages.add(buildMessage(opp));
        }

        if (messages.isEmpty()) {
            return 0;
        }

        Integer sent = 0;
        try {
            // One invocation for the whole batch; allOrNothing = false so one failure
            // does not prevent the other emails from going out.
            List<Messaging.SendEmailResult> results = Messaging.sendEmail(messages, false);
            for (Integer i = 0; i < results.size(); i++) {
                Messaging.SendEmailResult result = results[i];
                if (result.isSuccess()) {
                    sent++;
                } else {
                    for (Messaging.SendEmailError err : result.getErrors()) {
                        System.debug(LoggingLevel.ERROR,
                            'Renewal reminder failed for opportunity ' + opportunities[i].Id +
                            ': ' + err.getStatusCode() + ' - ' + err.getMessage());
                    }
                }
            }
        } catch (System.EmailException e) {
            // Org-level problems (e.g. deliverability set to "System email only")
            // are thrown rather than returned per message.
            System.debug(LoggingLevel.ERROR, 'Renewal reminders could not be sent: ' + e.getMessage());
            return 0;
        }

        return sent;
    }

    private static Messaging.SingleEmailMessage buildMessage(Opportunity opp) {
        Messaging.SingleEmailMessage mail = new Messaging.SingleEmailMessage();
        mail.setTargetObjectId(opp.OwnerId);
        mail.setSaveAsActivity(false); // required when the target is a User
        mail.setSubject(SUBJECT_PREFIX + opp.Name);

        String closeDateText = opp.CloseDate != null ? opp.CloseDate.format() : 'not set';
        mail.setPlainTextBody(
            'Hello,\n\n' +
            'The opportunity "' + opp.Name + '" is due for renewal.\n' +
            'Close date: ' + closeDateText + '\n\n' +
            'Please review it and follow up with the customer.\n'
        );
        return mail;
    }
}
