/**
 * Keeps Contact.MailingCountry in sync with Account.BillingCountry when an
 * account's BillingCountry changes (e.g. the company moves its headquarters).
 *
 * A contact is updated only if its MailingCountry is blank or equals the
 * account's previous BillingCountry. Contacts that work abroad (any other
 * MailingCountry) are left untouched.
 *
 * Runs without sharing on purpose: this is a system-level data sync and must
 * apply to all related contacts regardless of the running user's visibility.
 *
 * Bulk-safe: exactly one selective SOQL query (filtered on the indexed
 * AccountId field and on candidate MailingCountry values) and one DML statement
 * per trigger chunk. A full unfiltered Contact query is deliberately avoided:
 * with millions of contacts it would exceed the 50,000 query-row and heap limits.
 */
public without sharing class AccountCountrySync {

    public static void syncContactCountries(List<Account> newAccounts, Map<Id, Account> oldMap) {
        if (newAccounts == null || newAccounts.isEmpty() || oldMap == null) {
            return;
        }

        // AccountId -> previous BillingCountry (normalized; null if blank)
        Map<Id, String> oldCountryByAccount = new Map<Id, String>();
        // AccountId -> new BillingCountry
        Map<Id, String> newCountryByAccount = new Map<Id, String>();
        Set<String> oldCountries = new Set<String>();

        for (Account acc : newAccounts) {
            Account oldAcc = oldMap.get(acc.Id);
            if (oldAcc == null) {
                continue;
            }
            String newCountry = normalize(acc.BillingCountry);
            String oldCountry = normalize(oldAcc.BillingCountry);

            // Apex string == is case-insensitive; a case-only edit is not a move.
            if (newCountry == oldCountry) {
                continue;
            }
            // Do not propagate a cleared BillingCountry to contacts (avoid data loss).
            if (newCountry == null) {
                continue;
            }

            oldCountryByAccount.put(acc.Id, oldCountry);
            newCountryByAccount.put(acc.Id, newCountry);
            if (oldCountry != null) {
                oldCountries.add(oldCountry);
            }
        }

        if (newCountryByAccount.isEmpty()) {
            return;
        }

        Set<Id> accountIds = newCountryByAccount.keySet();
        List<Contact> contactsToUpdate = new List<Contact>();

        // Single selective query: indexed AccountId filter plus candidate-country filter.
        for (Contact con : [
                SELECT Id, AccountId, MailingCountry
                FROM Contact
                WHERE AccountId IN :accountIds
                  AND (MailingCountry = null OR MailingCountry IN :oldCountries)
        ]) {
            String contactCountry = normalize(con.MailingCountry);
            String previousAccountCountry = oldCountryByAccount.get(con.AccountId);

            // Match against this contact's own account's previous country.
            if (contactCountry == null || contactCountry == previousAccountCountry) {
                String targetCountry = newCountryByAccount.get(con.AccountId);
                if (con.MailingCountry != targetCountry) {
                    contactsToUpdate.add(new Contact(Id = con.Id, MailingCountry = targetCountry));
                }
            }
        }

        if (!contactsToUpdate.isEmpty()) {
            // All-or-none: keep accounts and contacts consistent; on failure the
            // account update rolls back and the integration can retry.
            update contactsToUpdate;
        }
    }

    private static String normalize(String value) {
        return String.isBlank(value) ? null : value.trim();
    }
}
```

