```javascript
import { LightningElement } from 'lwc';
import searchContacts from '@salesforce/apex/ContactController.searchContacts';

const DEBOUNCE_DELAY_MS = 300;
const MIN_SEARCH_LENGTH = 2;

export default class ContactSearch extends LightningElement {
    contacts = [];
    errorMessage;

    _debounceTimer;
    _latestRequestId = 0;

    get hasResults() {
        return Array.isArray(this.contacts) && this.contacts.length > 0;
    }

    get hasError() {
        return !!this.errorMessage;
    }

    handleChange(event) {
        const rawValue =
            event.detail && event.detail.value !== undefined
                ? event.detail.value
                : event.target.value;
        const searchTerm = (rawValue || '').trim();

        // Drop any pending search; each keystroke restarts the debounce window.
        this._cancelPendingSearch();

        if (searchTerm.length < MIN_SEARCH_LENGTH) {
            // Invalidate any request still in flight so its response is ignored.
            this._latestRequestId++;
            this.contacts = [];
            this.errorMessage = undefined;
            return;
        }

        // eslint-disable-next-line @lwc/lwc/no-async-operation
        this._debounceTimer = setTimeout(() => {
            this._debounceTimer = undefined;
            this._runSearch(searchTerm);
        }, DEBOUNCE_DELAY_MS);
    }

    disconnectedCallback() {
        this._cancelPendingSearch();
        // Ignore any response that arrives after removal.
        this._latestRequestId++;
    }

    async _runSearch(searchTerm) {
        const requestId = ++this._latestRequestId;
        try {
            const result = await searchContacts({ searchTerm });
            if (requestId !== this._latestRequestId) {
                return; // stale response
            }
            this.contacts = result || [];
            this.errorMessage = undefined;
        } catch (error) {
            if (requestId !== this._latestRequestId) {
                return; // stale error
            }
            this.contacts = [];
            this.errorMessage =
                error && error.body && error.body.message
                    ? error.body.message
                    : 'An unknown error occurred.';
        }
    }

    _cancelPendingSearch() {
        if (this._debounceTimer) {
            clearTimeout(this._debounceTimer);
            this._debounceTimer = undefined;
        }
    }
}
