import { LightningElement, api, wire } from 'lwc';
import { updateRecord } from 'lightning/uiRecordApi';
import { refreshApex } from '@salesforce/apex';
import { ShowToastEvent } from 'lightning/platformShowToastEvent';
import getContacts from '@salesforce/apex/ContactController.getContacts';

const COLUMNS = [
    { label: 'Name', fieldName: 'Name', type: 'text', editable: false },
    { label: 'Title', fieldName: 'Title', type: 'text', editable: true },
    { label: 'Phone', fieldName: 'Phone', type: 'phone', editable: true },
    { label: 'Email', fieldName: 'Email', type: 'email', editable: true }
];

export default class AccountContactsTable extends LightningElement {
    @api recordId;

    columns = COLUMNS;
    draftValues = [];
    contacts = [];
    error;

    // Full wire result, kept so refreshApex can refresh the cached data.
    wiredContactsResult;

    @wire(getContacts, { accountId: '$recordId' })
    wiredContacts(result) {
        this.wiredContactsResult = result;
        const { data, error } = result;
        if (data) {
            this.contacts = data;
            this.error = undefined;
        } else if (error) {
            this.contacts = [];
            this.error = error;
        }
    }

    get errorMessage() {
        if (!this.error) {
            return undefined;
        }
        return this.reduceError(this.error);
    }

    async handleSave(event) {
        const drafts = event.detail.draftValues || [];
        const recordInputs = drafts.map((draft) => ({ fields: { ...draft } }));

        try {
            // Save every draft row in parallel and wait for all of them.
            await Promise.all(recordInputs.map((recordInput) => updateRecord(recordInput)));
        } catch (error) {
            this.dispatchEvent(
                new ShowToastEvent({
                    title: 'Could not save contacts',
                    message: this.reduceError(error),
                    variant: 'error'
                })
            );
            return;
        }

        this.dispatchEvent(
            new ShowToastEvent({
                title: 'Contacts updated',
                message: 'Contact changes were saved.',
                variant: 'success'
            })
        );
        this.draftValues = [];
        await refreshApex(this.wiredContactsResult);
    }

    reduceError(error) {
        if (error && error.body && error.body.message) {
            return error.body.message;
        }
        if (error && Array.isArray(error.body) && error.body.length) {
            return error.body.map((e) => e.message).join(', ');
        }
        if (error && error.message) {
            return error.message;
        }
        return 'Unknown error';
    }
}
