    handleRetry() {
        // Ignore extra clicks while a call is already running.
        if (this.isLoading) {
            return;
        }
        this.loadOpportunities();
    }

    get hasError() {
        return !this.isLoading && !!this.error;
    }

    get errorMessage() {
        const err = this.error;
        if (!err) {
            return '';
        }
        if (err.body && err.body.message) {
            return err.body.message;
        }
        if (err.body && Array.isArray(err.body) && err.body.length && err.body[0].message) {
            return err.body[0].message;
        }
        return err.message || 'Unknown error';
    }

    get hasOpportunities() {
        return (
            !this.isLoading &&
            !this.error &&
            Array.isArray(this.opportunities) &&
            this.opportunities.length > 0
        );
    }

    get isEmpty() {
        return (
            !this.isLoading &&
            !this.error &&
            Array.isArray(this.opportunities) &&
            this.opportunities.length === 0
