        try {
            await deleteRecord(row.Id);
            this.rows = this.rows.filter((r) => r.Id !== row.Id);
            this.dispatchEvent(
                new ShowToastEvent({
                    title: 'Opportunity deleted',
                    message: `${row.Name} was deleted.`,
                    variant: 'success'
                })
            );
        } catch (error) {
            this.dispatchEvent(
                new ShowToastEvent({
                    title: 'Delete failed',
                    message: error?.body?.message,
                    variant: 'error'
                })
