```javascript
import { LightningElement } from 'lwc';
import getQueueStats from '@salesforce/apex/QueueController.getQueueStats';

const REFRESH_INTERVAL_MS = 60000;

export default class QueueMonitor extends LightningElement {
    stats;
    errorMessage;

    _intervalId = null;
    _inFlight = false;
    _connected = false;
    _boundVisibilityHandler;

    constructor() {
        super();
        this._boundVisibilityHandler = this.handleVisibilityChange.bind(this);
    }

    get hasStats() {
        return this.stats !== undefined && this.stats !== null;
    }

    get waiting() {
        return this.stats ? this.stats.waiting : null;
    }

    get longestWaitMinutes() {
        return this.stats ? this.stats.longestWaitMinutes : null;
    }

    connectedCallback() {
        this._connected = true;
        // Guard against duplicate listeners/loops if connected twice without disconnect.
        document.removeEventListener('visibilitychange', this._boundVisibilityHandler);
        document.addEventListener('visibilitychange', this._boundVisibilityHandler);
        this.stopPolling();
        if (!this.isHidden()) {
            this.startPolling();
        }
    }

    disconnectedCallback() {
        this._connected = false;
        this.stopPolling();
        document.removeEventListener('visibilitychange', this._boundVisibilityHandler);
    }

    handleVisibilityChange() {
        if (!this._connected) {
            return;
        }
        if (this.isHidden()) {
            this.stopPolling();
        } else {
            // Becoming visible: load immediately and restart the 60s cadence.
            this.stopPolling();
            this.startPolling();
        }
    }

    isHidden() {
        return document.visibilityState === 'hidden';
    }

    startPolling() {
        this.loadStats();
        // eslint-disable-next-line @lwc/lwc/no-async-operation
        this._intervalId = setInterval(() => {
            this.loadStats();
        }, REFRESH_INTERVAL_MS);
    }

    stopPolling() {
        if (this._intervalId !== null) {
            clearInterval(this._intervalId);
            this._intervalId = null;
        }
    }

    async loadStats() {
        if (!this._connected || this.isHidden() || this._inFlight) {
            return;
        }
        this._inFlight = true;
        try {
            const result = await getQueueStats();
            this.stats = result;
            this.errorMessage = undefined;
        } catch (error) {
            this.errorMessage =
                (error && error.body && error.body.message) ||
                (error && error.message) ||
                'Unknown error';
        } finally {
            this._inFlight = false;
        }
    }
}
