```javascript
import { LightningElement } from 'lwc';
import { ShowToastEvent } from 'lightning/platformShowToastEvent';
import register from '@salesforce/apex/RegistrationController.register';

const PERSONAL_DOMAINS = new Set(['gmail.com', 'yahoo.com', 'hotmail.com', 'outlook.com']);
const WORK_EMAIL_MESSAGE = 'Use your work email address.';

export default class EventRegistrationForm extends LightningElement {
    fullName;
    email;
    company;
    isSubmitting = false;

    handleChange(event) {
        const field = event.target.dataset.field;
        if (field === 'fullName' || field === 'email' || field === 'company') {
            this[field] = event.detail.value;
        }
    }

    isPersonalEmail(value) {
        if (!value || typeof value !== 'string') {
            return false;
        }
        const atIndex = value.lastIndexOf('@');
        if (atIndex < 0) {
            return false;
        }
        const domain = value.slice(atIndex + 1).trim().toLowerCase();
        return PERSONAL_DOMAINS.has(domain);
    }

    async handleRegister() {
        if (this.isSubmitting) {
            return;
        }

        // 1. Work-email check (custom validity) before reporting validity
        const emailInput = this.template.querySelector('lightning-input[data-field="email"]');
        if (emailInput) {
            emailInput.setCustomValidity(
                this.isPersonalEmail(this.email) ? WORK_EMAIL_MESSAGE : ''
            );
        }

        // 2. Report validity on every input (no short-circuit)
        const inputs = [...this.template.querySelectorAll('lightning-input')];
        const allValid = inputs.reduce((valid, input) => {
            const inputValid = input.reportValidity();
            return valid && inputValid;
        }, true);

        // 3. Stop if anything is invalid
        if (!allValid) {
            return;
        }

        this.isSubmitting = true;
        try {
            await register({
                fullName: this.fullName,
                email: this.email,
                company: this.company
            });
            this.dispatchEvent(
                new ShowToastEvent({
                    title: 'Registered',
                    message: 'You are registered for the event.',
                    variant: 'success'
                })
            );
        } catch (error) {
            this.dispatchEvent(
                new ShowToastEvent({
                    title: 'Registration failed',
                    message: error?.body?.message,
                    variant: 'error'
                })
            );
        } finally {
            this.isSubmitting = false;
        }
    }
}
