```javascript
import { LightningElement, api } from 'lwc';

const NAV_KEYS = new Set(['ArrowDown', 'ArrowUp', 'Home', 'End']);
const SELECT_KEYS = new Set(['Enter', ' ']);

export default class StatusListbox extends LightningElement {
    @api label;

    _options = [];
    _value;
    activeIndex = -1;

    @api
    get options() {
        return this._options;
    }
    set options(val) {
        const previousActive = this._options[this.activeIndex];
        this._options = Array.isArray(val) ? val : [];

        // Keep the active option if it still exists, otherwise fall back.
        let idx = -1;
        if (previousActive) {
            idx = this.indexOfValue(previousActive.value);
        }
        this.activeIndex = idx >= 0 ? idx : this.defaultActiveIndex();
    }

    @api
    get value() {
        return this._value;
    }
    set value(val) {
        this._value = val;
        const idx = this.indexOfValue(val);
        this.activeIndex = idx >= 0 ? idx : this.defaultActiveIndex();
    }

    // ---------- helpers ----------

    indexOfValue(val) {
        if (val === undefined || val === null || val === '') {
            return -1;
        }
        return this._options.findIndex((opt) => opt && opt.value === val);
    }

    defaultActiveIndex() {
        const selected = this.indexOfValue(this._value);
        if (selected >= 0) {
            return selected;
        }
        return this._options.length > 0 ? 0 : -1;
    }

    optionId(index) {
        return `status-option-${index}`;
    }

    get normalizedActiveIndex() {
        const len = this._options.length;
        if (len === 0) {
            return -1;
        }
        if (this.activeIndex >= 0 && this.activeIndex < len) {
            return this.activeIndex;
        }
        return this.defaultActiveIndex();
    }

    // ---------- template getters ----------

    get activeDescendant() {
        const idx = this.normalizedActiveIndex;
        return idx >= 0 ? this.optionId(idx) : undefined;
    }

    get renderedOptions() {
        const selectedIndex = this.indexOfValue(this._value);
        const activeIndex = this.normalizedActiveIndex;
        return this._options.map((opt, index) => ({
            key: `${index}-${opt.value}`,
            id: this.optionId(index),
            index: String(index),
            value: opt.value,
            label: opt.label,
            ariaSelected: index === selectedIndex ? 'true' : 'false',
            className:
                'slds-listbox__item status-option' +
                (index === activeIndex ? ' status-option_active' : '') +
                (index === selectedIndex ? ' status-option_selected' : '')
        }));
    }

    // ---------- behaviour ----------

    selectIndex(index) {
        if (index < 0 || index >= this._options.length) {
            return;
        }
        this.activeIndex = index;
        const newValue = this._options[index].value;
        if (newValue === this._value) {
            return;
        }
        this._value = newValue;
        this.dispatchEvent(
            new CustomEvent('change', { detail: { value: newValue } })
        );
    }

    handleKeyDown(event) {
        const key = event.key;
        if (!NAV_KEYS.has(key) && !SELECT_KEYS.has(key)) {
            return; // keep default behaviour (e.g. Tab)
        }
        event.preventDefault();

        const len = this._options.length;
        if (len === 0) {
            return;
        }
        const current = this.normalizedActiveIndex;

        switch (key) {
            case 'ArrowDown':
                this.activeIndex = Math.min(current + 1, len - 1);
                break;
            case 'ArrowUp':
                this.activeIndex = Math.max(current - 1, 0);
                break;
            case 'Home':
                this.activeIndex = 0;
                break;
            case 'End':
                this.activeIndex = len - 1;
                break;
            default:
                // Enter or space
                this.selectIndex(current);
                break;
        }
    }

    handleOptionClick(event) {
        const index = parseInt(event.currentTarget.dataset.index, 10);
        if (!Number.isNaN(index)) {
            this.selectIndex(index);
        }
    }
}
