```apex
/**
 * Sets each contact's current employer using NPSP's standard affiliation mechanism.
 *
 * The main step is updating Contact.npsp__Primary_Affiliation__c. NPSP's affiliation
 * trigger handler (AFFL_Affiliations_TDTM) then:
 *   - creates a Current, primary affiliation to the new organization, or marks an existing
 *     affiliation to that organization as primary;
 *   - makes the previous primary affiliation non-primary and Former, with an end date of today.
 *
 * The contact's AccountId is never changed, so the contact stays in its household.
 *
 * Governor usage per call: at most 2 SOQL queries and 2 DML statements of its own.
 */
public inherited sharing class EmployerService {

    private static final String STATUS_CURRENT = 'Current';

    public static void setCurrentEmployers(Map<Id, Id> employerByContactId) {
        if (employerByContactId == null || employerByContactId.isEmpty()) {
            return;
        }

        // Keep only valid Contact -> Account pairs.
        Map<Id, Id> orgByContactId = new Map<Id, Id>();
        for (Id contactId : employerByContactId.keySet()) {
            Id orgId = employerByContactId.get(contactId);
            if (contactId == null || orgId == null) {
                continue;
            }
            if (contactId.getSObjectType() != Contact.SObjectType
                    || orgId.getSObjectType() != Account.SObjectType) {
                continue;
            }
            orgByContactId.put(contactId, orgId);
        }
        if (orgByContactId.isEmpty()) {
            return;
        }

        // SOQL 1: the contacts and their current primary affiliation lookup.
        Map<Id, Contact> contactsById = new Map<Id, Contact>([
            SELECT Id, npsp__Primary_Affiliation__c
            FROM Contact
            WHERE Id IN :orgByContactId.keySet()
        ]);
        if (contactsById.isEmpty()) {
            return;
        }

        Set<Id> orgIds = new Set<Id>(orgByContactId.values());

        // SOQL 2: existing affiliations between each contact and its requested organization.
        // The sort order prefers the primary, Current, newest record for each pair.
        Map<Id, npe5__Affiliation__c> existingByContactId = new Map<Id, npe5__Affiliation__c>();
        for (npe5__Affiliation__c affl : [
                SELECT Id, npe5__Contact__c, npe5__Organization__c, npe5__Status__c,
                       npe5__Primary__c, npe5__EndDate__c
                FROM npe5__Affiliation__c
                WHERE npe5__Contact__c IN :contactsById.keySet()
                  AND npe5__Organization__c IN :orgIds
                ORDER BY npe5__Primary__c DESC, npe5__Status__c ASC, CreatedDate DESC]) {
            if (orgByContactId.get(affl.npe5__Contact__c) != affl.npe5__Organization__c) {
                continue; // affiliation to an org requested for a different contact
            }
            if (!existingByContactId.containsKey(affl.npe5__Contact__c)) {
                existingByContactId.put(affl.npe5__Contact__c, affl);
            }
        }

        List<Contact> contactsToUpdate = new List<Contact>();
        List<npe5__Affiliation__c> affiliationsToUpsert = new List<npe5__Affiliation__c>();

        for (Contact con : contactsById.values()) {
            Id orgId = orgByContactId.get(con.Id);
            npe5__Affiliation__c existing = existingByContactId.get(con.Id);

            Boolean lookupOk = con.npsp__Primary_Affiliation__c == orgId;
            Boolean existingIsCurrent = existing != null
                && existing.npe5__Status__c == STATUS_CURRENT
                && existing.npe5__EndDate__c == null;
            Boolean afflOk = existingIsCurrent && existing.npe5__Primary__c == true;

            if (lookupOk && afflOk) {
                continue; // already the primary employer: nothing changes
            }

            if (!lookupOk) {
                // Standard NPSP mechanism: change the primary affiliation lookup only.
                // Do not touch AccountId, so the household is preserved.
                contactsToUpdate.add(new Contact(
                    Id = con.Id,
                    npsp__Primary_Affiliation__c = orgId
                ));
                // NPSP reuses an existing affiliation to this org and marks it primary.
                // If that record was Former or end-dated, reactivate it.
                if (existing != null && !existingIsCurrent) {
                    affiliationsToUpsert.add(reactivate(existing.Id));
                }
            } else {
                // The lookup already points to the org, but no Current primary affiliation backs it.
                if (existing == null) {
                    affiliationsToUpsert.add(new npe5__Affiliation__c(
                        npe5__Contact__c = con.Id,
                        npe5__Organization__c = orgId,
                        npe5__Status__c = STATUS_CURRENT,
                        npe5__Primary__c = true,
                        npe5__StartDate__c = Date.today()
                    ));
                } else {
                    affiliationsToUpsert.add(reactivate(existing.Id));
                }
            }
        }

        // DML 1: NPSP's contact trigger creates or reuses the new primary affiliation and
        // marks the previous primary as Former, non-primary, ended today.
        if (!contactsToUpdate.isEmpty()) {
            update contactsToUpdate;
        }

        // DML 2: reactivate reused affiliations and create any missing ones (insert + update in one call).
        if (!affiliationsToUpsert.isEmpty()) {
            upsert affiliationsToUpsert;
        }
    }

    private static npe5__Affiliation__c reactivate(Id affiliationId) {
        return new npe5__Affiliation__c(
            Id = affiliationId,
            npe5__Status__c = STATUS_CURRENT,
            npe5__Primary__c = true,
            npe5__EndDate__c = null
        );
    }
}
```

**Design notes**
- **Standard NPSP mechanism.** The class only changes `npsp__Primary_Affiliation__c`. NPSP's affiliation trigger then creates the Current, primary affiliation, or reuses an existing one to that organization so there is no duplicate. It also marks the old primary as Former and non-primary, with an end date of today.
- **Assumptions about NPSP behaviour.** The task states that NPSP marks the old primary Former. The class also relies on NPSP reusing an existing affiliation to the same organization instead of creating a second one. I did not verify either behaviour in this org. Confirm both in a sandbox before deploying.
- **Household preserved.** `AccountId` is never touched, so each contact stays in its household account.
- **No-op case.** If the lookup already points to the organization and that affiliation is Current and primary, the contact is skipped.
- **Edge cases fixed.** Two situations are repaired with an upsert:
  - The lookup is already set, but the affiliation is missing, Former, or end-dated.
  - NPSP reuses an affiliation that was Former and needs reactivating.
- **Governor limits.** The class uses exactly 2 SOQL queries and at most 2 DML statements, with no queries or DML inside loops. It handles 200 contacts per call.
- **Input handling.** Null or empty maps, null entries and Ids of the wrong type are ignored.
- **Sharing.** `inherited sharing` means the caller's sharing context applies.

