/**
 * Routes website gifts through NPSP's Data Importer (BDI) so NPSP applies its own
 * contact matching, household creation and donation processing rules.
 * Each staged npsp__DataImport__c record is kept as the audit trail.
 */
public with sharing class GiftImportService {

    public static final String STATUS_IMPORTED = 'Imported';

    public class WebGift {
        public String firstName;
        public String lastName;
        public String email;        // the donor's personal email
        public Decimal amount;
        public Date giftDate;
    }

    public class ImportResult {
        public Boolean success;
        public Id contactId;        // the matched or created contact
        public Id opportunityId;    // the created donation
        public String errorMessage; // NPSP's failure information when success is false
    }

    public static List<ImportResult> importGifts(List<WebGift> gifts) {
        List<ImportResult> results = new List<ImportResult>();
        if (gifts == null || gifts.isEmpty()) {
            return results;
        }

        // 1. Build one staging record per gift. Null gifts get a failure result.
        List<npsp__DataImport__c> staged = new List<npsp__DataImport__c>();
        List<Integer> stagedIndexes = new List<Integer>();
        for (Integer i = 0; i < gifts.size(); i++) {
            ImportResult r = new ImportResult();
            r.success = false;
            results.add(r);

            WebGift g = gifts[i];
            if (g == null) {
                r.errorMessage = 'Gift is null.';
                continue;
            }
            staged.add(new npsp__DataImport__c(
                npsp__Contact1_Firstname__c      = g.firstName,
                npsp__Contact1_Lastname__c       = g.lastName,
                npsp__Contact1_Personal_Email__c = g.email,
                npsp__Donation_Amount__c         = g.amount,
                npsp__Donation_Date__c           = g.giftDate,
                npsp__Donation_Donor__c          = 'Contact1'
            ));
            stagedIndexes.add(i);
        }
        if (staged.isEmpty()) {
            return results;
        }

        // 2. Insert the staging records. Use partial success so one bad row does not
        //    stop the others. The records stay in the org as the audit trail.
        Database.SaveResult[] saveResults =
            Database.insert(staged, false, AccessLevel.USER_MODE);

        List<npsp__DataImport__c> toProcess = new List<npsp__DataImport__c>();
        Map<Id, Integer> resultIndexById = new Map<Id, Integer>();
        for (Integer s = 0; s < saveResults.size(); s++) {
            Integer resultIndex = stagedIndexes[s];
            if (saveResults[s].isSuccess()) {
                toProcess.add(staged[s]);
                resultIndexById.put(saveResults[s].getId(), resultIndex);
            } else {
                List<String> msgs = new List<String>();
                for (Database.Error e : saveResults[s].getErrors()) {
                    msgs.add(e.getMessage());
                }
                results[resultIndex].errorMessage = String.join(msgs, '; ');
            }
        }
        if (toProcess.isEmpty()) {
            return results;
        }

        // 3. Process synchronously in this transaction with NPSP's data import API
        //    and the org's Data Import settings. NPSP marks rows it rejects as Failed
        //    individually and continues with the rest.
        npsp.BDI_DataImport_API.processDataImportRecords(getDataImportSettings(), toProcess, false);

        // 4. Build results from the processed Data Import records, as NPSP saved them.
        for (npsp__DataImport__c di : [
                SELECT Id, npsp__Status__c, npsp__Contact1Imported__c,
                       npsp__DonationImported__c, npsp__FailureInformation__c
                FROM npsp__DataImport__c
                WHERE Id IN :resultIndexById.keySet()
                WITH USER_MODE]) {
            ImportResult r = results[resultIndexById.get(di.Id)];
            r.contactId = di.npsp__Contact1Imported__c;
            r.opportunityId = di.npsp__DonationImported__c;
            r.success = (di.npsp__Status__c == STATUS_IMPORTED);
            if (!r.success) {
                r.errorMessage = String.isNotBlank(di.npsp__FailureInformation__c)
                    ? di.npsp__FailureInformation__c
                    : 'Data Import record was not imported (status: ' + di.npsp__Status__c + ').';
            }
        }
        return results;
    }

    /**
     * Returns the org's Data Import settings (hierarchy custom setting). If no settings
     * record exists, getInstance() returns the field defaults. NPSP's documented defaults
     * are applied as a safety net when key values are blank.
     */
    private static npsp__Data_Import_Settings__c getDataImportSettings() {
        npsp__Data_Import_Settings__c settings = npsp__Data_Import_Settings__c.getInstance();
        if (settings == null) {
            settings = new npsp__Data_Import_Settings__c();
        }
        if (String.isBlank(settings.npsp__Contact_Matching_Rule__c)) {
            settings.npsp__Contact_Matching_Rule__c = 'Firstname,Lastname,Email';
        }
        if (String.isBlank(settings.npsp__Donation_Matching_Behavior__c)) {
            settings.npsp__Donation_Matching_Behavior__c = 'No Match';
        }
        return settings;
    }
}
```

**How it works:**
- **Staging and processing:** The class inserts the staging records with partial success. It then calls `npsp.BDI_DataImport_API.processDataImportRecords` once for all of them, synchronously. It passes the org's `npsp__Data_Import_Settings__c` and does not update gift batch totals. It sets `npsp__Donation_Donor__c = 'Contact1'` so each gift attaches to the matched or created contact and household.
- **Settings fallback:** If the contact matching rule or donation matching behaviour is blank, the class uses NPSP's documented defaults. These are first name, last name and email, and "No Match" for donations.
- **Results:** After processing, the class re-queries the Data Import records and builds each result from what NPSP wrote back. `success` means `npsp__Status__c == 'Imported'`. Results come back in input order, using an index map keyed by Data Import Id.
- **Rejected rows:** NPSP marks rejected rows `Failed` one at a time, so they do not stop the others. Their result carries `npsp__FailureInformation__c`.
- **Other failures:** A failed staging insert or a null gift also gets a per-row failure result.
- **Bulk safety:** There is one insert, one processing call and one query, with no SOQL or DML in loops, so 200 gifts in one call works.
- **Security:** The class runs `with sharing`, and its own DML and query run in user mode.
- **Audit trail:** The staged Data Import records are never deleted.

