/**
 * Creates NPSP Enhanced Recurring Donations (ERD) for monthly giving sign-ups
 * that come from the donation form.
 *
 * Design notes:
 *  - Uses only Enhanced Recurring Donation fields: RecurringType, InstallmentFrequency,
 *    Day_of_Month, StartDate and Status. Legacy-only fields such as Schedule_Type,
 *    Open_Ended_Status and Next_Payment_Date are left for NPSP to manage.
 *  - A form value of 31 is stored as the ERD picklist value 'Last_Day'.
 *    The npsp__Always_Use_Last_Day_Of_Month__c checkbox is a legacy field and is not used.
 *  - No Opportunities are created. NPSP's Recurring Donation trigger generates the
 *    installment Opportunities.
 *  - Validation runs before any DML. The class uses no SOQL and one DML statement.
 */
public with sharing class RecurringGiftService {

    public class RecurringGiftException extends Exception {}

    public class GiftRequest {
        public Id contactId;
        public Decimal amount;
        public Integer dayOfMonth;    // 1-31
        public Date startDate;
        public Integer installments;  // null or 0 = no end date
        public String paymentMethod;  // 'Credit Card', 'ACH' or 'Check'
    }

    private static final String RECURRING_TYPE_OPEN  = 'Open';
    private static final String RECURRING_TYPE_FIXED = 'Fixed';
    private static final String PERIOD_MONTHLY       = 'Monthly';
    private static final String STATUS_ACTIVE        = 'Active';
    private static final String DAY_LAST_DAY         = 'Last_Day';

    public static List<Id> createMonthlyGifts(List<GiftRequest> requests) {
        List<Id> result = new List<Id>();
        if (requests == null || requests.isEmpty()) {
            return result;
        }

        // 1. Validate all requests before any DML.
        for (Integer i = 0; i < requests.size(); i++) {
            validate(requests[i], i);
        }

        // 2. Build the records in request order.
        List<npe03__Recurring_Donation__c> rds = new List<npe03__Recurring_Donation__c>();
        for (GiftRequest req : requests) {
            rds.add(buildRecurringDonation(req));
        }

        // 3. A single all-or-none DML statement that enforces the running user's CRUD/FLS.
        Database.insert(rds, true, AccessLevel.USER_MODE);

        for (npe03__Recurring_Donation__c rd : rds) {
            result.add(rd.Id);
        }
        return result;
    }

    private static void validate(GiftRequest req, Integer index) {
        String prefix = 'Request ' + index + ': ';
        if (req == null) {
            throw new RecurringGiftException(prefix + 'request is null.');
        }
        if (req.contactId == null) {
            throw new RecurringGiftException(prefix + 'contactId is required.');
        }
        if (req.amount == null || req.amount <= 0) {
            throw new RecurringGiftException(prefix + 'amount must be greater than zero.');
        }
        if (req.dayOfMonth == null || req.dayOfMonth < 1 || req.dayOfMonth > 31) {
            throw new RecurringGiftException(prefix + 'dayOfMonth must be between 1 and 31.');
        }
        if (req.startDate == null) {
            throw new RecurringGiftException(prefix + 'startDate is required.');
        }
        if (req.installments != null && req.installments < 0) {
            throw new RecurringGiftException(prefix + 'installments cannot be negative.');
        }
    }

    private static npe03__Recurring_Donation__c buildRecurringDonation(GiftRequest req) {
        npe03__Recurring_Donation__c rd = new npe03__Recurring_Donation__c(
            npe03__Contact__c              = req.contactId,
            npe03__Amount__c               = req.amount,
            npe03__Installment_Period__c   = PERIOD_MONTHLY,
            npsp__InstallmentFrequency__c  = 1,
            npsp__Day_of_Month__c          = req.dayOfMonth == 31
                                                ? DAY_LAST_DAY
                                                : String.valueOf(req.dayOfMonth),
            npsp__StartDate__c             = req.startDate,
            npsp__Status__c                = STATUS_ACTIVE,
            npsp__PaymentMethod__c         = req.paymentMethod
        );

        Boolean isOpenEnded = req.installments == null || req.installments == 0;
        if (isOpenEnded) {
            rd.npsp__RecurringType__c = RECURRING_TYPE_OPEN;
        } else {
            rd.npsp__RecurringType__c = RECURRING_TYPE_FIXED;
            rd.npe03__Installments__c = req.installments;
        }
        return rd;
    }
}
```

