/**
 * Splits an Opportunity across NPSP General Accounting Units by percentage.
 *
 * Allocations are created with npsp__Percent__c only (npsp__Amount__c left blank).
 * NPSP's allocation trigger handler (ALLO_Allocations_TDTM) calculates the amount
 * from the opportunity amount. It recalculates percent-based allocations whenever
 * the opportunity amount changes, so the split stays correct without extra code.
 */
public with sharing class GauAllocationService {

    public class AllocationException extends Exception {}

    private static final Decimal MAX_TOTAL_PERCENT = 100;

    public static List<npsp__Allocation__c> allocateByPercent(Id opportunityId, Map<Id, Decimal> percentByGauId) {

        // ---------- Validation (no data is changed in this section) ----------
        if (opportunityId == null
                || opportunityId.getSobjectType() != Opportunity.SObjectType) {
            throw new AllocationException('A valid Opportunity Id is required.');
        }
        if (percentByGauId == null || percentByGauId.isEmpty()) {
            throw new AllocationException('At least one General Accounting Unit percentage is required.');
        }

        List<Opportunity> opps = [
            SELECT Id
            FROM Opportunity
            WHERE Id = :opportunityId
            WITH USER_MODE
            LIMIT 1
        ];
        if (opps.isEmpty()) {
            throw new AllocationException('Opportunity ' + opportunityId + ' was not found or is not accessible.');
        }

        Decimal total = 0;
        for (Id gauId : percentByGauId.keySet()) {
            if (gauId == null
                    || gauId.getSobjectType() != npsp__General_Accounting_Unit__c.SObjectType) {
                throw new AllocationException('Invalid General Accounting Unit Id: ' + gauId);
            }
            Decimal pct = percentByGauId.get(gauId);
            if (pct == null || pct <= 0) {
                throw new AllocationException(
                    'Percentage for General Accounting Unit ' + gauId + ' must be greater than 0.');
            }
            total += pct;
        }
        if (total > MAX_TOTAL_PERCENT) {
            throw new AllocationException(
                'Allocation percentages total ' + total + '%, which exceeds 100%.');
        }

        Set<Id> gauIds = percentByGauId.keySet();
        Map<Id, npsp__General_Accounting_Unit__c> gauById = new Map<Id, npsp__General_Accounting_Unit__c>([
            SELECT Id, Name, npsp__Active__c
            FROM npsp__General_Accounting_Unit__c
            WHERE Id IN :gauIds
            WITH USER_MODE
        ]);
        for (Id gauId : gauIds) {
            npsp__General_Accounting_Unit__c gau = gauById.get(gauId);
            if (gau == null) {
                throw new AllocationException(
                    'General Accounting Unit ' + gauId + ' was not found or is not accessible.');
            }
            if (!gau.npsp__Active__c) {
                throw new AllocationException(
                    'General Accounting Unit "' + gau.Name + '" is inactive.');
            }
        }

        // ---------- Build new allocations (percent only, so NPSP owns the amount) ----------
        List<npsp__Allocation__c> newAllocations = new List<npsp__Allocation__c>();
        for (Id gauId : gauIds) {
            newAllocations.add(new npsp__Allocation__c(
                npsp__Opportunity__c = opportunityId,
                npsp__General_Accounting_Unit__c = gauId,
                npsp__Percent__c = percentByGauId.get(gauId)
            ));
        }

        List<npsp__Allocation__c> existing = [
            SELECT Id
            FROM npsp__Allocation__c
            WHERE npsp__Opportunity__c = :opportunityId
            WITH USER_MODE
        ];

        // ---------- Replace atomically ----------
        // Delete first, so NPSP's "allocations exceed amount" check only sees the new set.
        Savepoint sp = Database.setSavepoint();
        try {
            if (!existing.isEmpty()) {
                delete as user existing;
            }
            insert as user newAllocations;
        } catch (Exception e) {
            Database.rollback(sp);
            throw new AllocationException(
                'Could not save GAU allocations: ' + e.getMessage(), e);
        }

        return newAllocations;
    }
}
```

**Design notes:**
- **Validation before any change:** every check runs before any DML. The checks cover the opportunity Id, the map, each GAU Id type, each percentage, the total of at most 100%, and that each GAU exists and is active. A total below 100% is allowed.
- **Atomic replace:** a savepoint wraps the delete and insert. If NPSP or a validation rule rejects the insert, the old allocations are restored. The error is then rethrown as an `AllocationException`.
- **Delete before insert:** this order means NPSP's check that allocations do not exceed the opportunity amount sees only the new allocations.
- **Scope of the replace:** only allocations that look up to this opportunity are replaced. Payment allocations (`npsp__Payment__c`) are left alone.
- **Security:** the class runs `with sharing`, uses `WITH USER_MODE` queries and does user-mode DML. Staff therefore need access to the opportunity, GAUs and allocations.
- **Bulk-safe:** the method uses a fixed number of queries and DML statements, regardless of how many GAUs are in the map.

