/**
 * Registers a family as a single NPSP Household Account.
 *
 * NPSP creates a new household for every contact inserted without an AccountId.
 * Inserting all members at once would therefore leave one household per contact.
 *
 * This service avoids that:
 *  1. It inserts the first (primary) contact alone, without an AccountId.
 *     NPSP creates exactly one Household Account (HH_Account record type),
 *     names it, generates greetings and sets it as the primary contact.
 *  2. It inserts the remaining members with AccountId set to that household.
 *     NPSP creates no further accounts and refreshes the household name.
 *  3. It checks the result: the record type must be HH_Account and the primary
 *     contact must be the first member. Otherwise it rolls back and fails.
 *
 * The whole operation runs under a savepoint, so it is all or nothing.
 */
public with sharing class HouseholdService {

    private static final String HH_RECORD_TYPE_DEV_NAME = 'HH_Account';

    public class HouseholdServiceException extends Exception {}

    public static Id createHousehold(List<Contact> members) {
        validate(members);

        Id householdRecordTypeId = getHouseholdRecordTypeId();
        Contact primary = members[0];
        List<Contact> others = new List<Contact>();
        for (Integer i = 1; i < members.size(); i++) {
            others.add(members[i]);
        }

        Savepoint sp = Database.setSavepoint();
        try {
            // 1. Primary contact alone -> NPSP creates exactly one household.
            insert as user primary;

            Contact insertedPrimary = [
                SELECT Id, AccountId, Account.RecordTypeId,
                       Account.npe01__One2OneContact__c
                FROM Contact
                WHERE Id = :primary.Id
                LIMIT 1
            ];

            Id householdId = insertedPrimary.AccountId;
            if (householdId == null) {
                throw new HouseholdServiceException(
                    'NPSP did not create a household for the primary contact. ' +
                    'Check that the Household Account model and NPSP triggers are enabled.');
            }
            if (insertedPrimary.Account.RecordTypeId != householdRecordTypeId) {
                throw new HouseholdServiceException(
                    'The account NPSP created is not a Household Account (' +
                    HH_RECORD_TYPE_DEV_NAME + ' record type).');
            }

            // 2. Remaining members join the same household. AccountId is set,
            //    so NPSP creates no extra accounts.
            if (!others.isEmpty()) {
                for (Contact c : others) {
                    c.AccountId = householdId;
                }
                insert as user others;
            }

            // 3. Make sure the first contact is the household's primary contact.
            Account household = [
                SELECT Id, npe01__One2OneContact__c
                FROM Account
                WHERE Id = :householdId
                LIMIT 1
            ];
            if (household.npe01__One2OneContact__c != primary.Id) {
                household.npe01__One2OneContact__c = primary.Id;
                update as user household;
            }

            primary.AccountId = householdId;
            return householdId;
        } catch (Exception e) {
            Database.rollback(sp);
            // Rollback does not clear Ids on in-memory records; reset them so the
            // caller can retry with the same list.
            for (Contact c : members) {
                c.Id = null;
                c.AccountId = null;
            }
            throw e;
        }
    }

    private static void validate(List<Contact> members) {
        if (members == null || members.isEmpty()) {
            throw new IllegalArgumentException('members must contain at least one Contact.');
        }
        for (Contact c : members) {
            if (c == null) {
                throw new IllegalArgumentException('members must not contain null entries.');
            }
            if (c.Id != null) {
                throw new IllegalArgumentException('All members must be new Contacts (no Id).');
            }
            if (c.AccountId != null) {
                throw new IllegalArgumentException('Members must not have an AccountId; the household is created by this service.');
            }
        }
    }

    private static Id getHouseholdRecordTypeId() {
        Schema.RecordTypeInfo rti = Schema.SObjectType.Account
            .getRecordTypeInfosByDeveloperName()
            .get(HH_RECORD_TYPE_DEV_NAME);
        if (rti == null) {
            throw new HouseholdServiceException(
                'Account record type ' + HH_RECORD_TYPE_DEV_NAME + ' was not found.');
        }
        return rti.getRecordTypeId();
    }
}
```

**Notes on this design:**
- The service never creates the account itself. Account Name is required on insert, which would force us to set it. Letting NPSP create the household from the first contact keeps NPSP's automatic naming and greetings, and gives it the household record type NPSP is configured to use.
- After step 1 the code checks that this record type is `HH_Account`, using `Schema.SObjectType.Account.getRecordTypeInfosByDeveloperName()` rather than a hard-coded Id. If anything fails, everything rolls back, so no empty or extra accounts are left behind.
- All DML runs in user mode (`insert as user`, `update as user`). The check-in app's user therefore needs create access to Contact and edit access to `Account.npe01__One2OneContact__c`.

