/**
 * Records an already-received gift the way NPSP expects.
 *
 * NPSP triggers may create records automatically when a Closed Won opportunity
 * with a primary contact is inserted:
 *  - a Donor contact role for the primary contact;
 *  - Household Member contact roles for the rest of the household;
 *  - a payment, when Payments are enabled.
 * Whether NPSP creates these depends on the org's settings. So after inserting
 * the opportunity, this class reconciles what exists instead of blindly inserting.
 * The end state is one contact role per household contact and exactly one paid payment.
 */
public with sharing class GiftService {

    @TestVisible private static final String DONOR_ROLE = 'Donor';
    @TestVisible private static final String HOUSEHOLD_MEMBER_ROLE = 'Household Member';
    private static final String DEFAULT_WON_STAGE = 'Closed Won';

    public static Id recordGift(Id contactId, Decimal amount, Date giftDate) {
        if (contactId == null) {
            throw new IllegalArgumentException('A contact is required.');
        }
        if (amount == null || amount <= 0) {
            throw new IllegalArgumentException('Amount must be greater than zero.');
        }
        if (giftDate == null) {
            throw new IllegalArgumentException('A gift date is required.');
        }

        List<Contact> donors = [
            SELECT Id, FirstName, LastName, AccountId
            FROM Contact
            WHERE Id = :contactId
            LIMIT 1
        ];
        if (donors.isEmpty()) {
            throw new IllegalArgumentException('Contact ' + contactId + ' does not exist.');
        }
        Contact donor = donors[0];
        if (donor.AccountId == null) {
            throw new IllegalArgumentException(
                'Contact ' + contactId + ' is not linked to a household account.');
        }
        Id householdId = donor.AccountId;

        Savepoint sp = Database.setSavepoint();
        try {
            Opportunity opp = new Opportunity(
                Name = buildName(donor, giftDate),
                AccountId = householdId,
                npsp__Primary_Contact__c = donor.Id,
                Amount = amount,
                CloseDate = giftDate,
                StageName = getWonStage()
            );
            insert opp;

            reconcileContactRoles(opp.Id, donor.Id, householdId);
            reconcilePayment(opp.Id, amount, giftDate);

            return opp.Id;
        } catch (Exception e) {
            Database.rollback(sp);
            throw e;
        }
    }

    // ------------------------------------------------------------------ helpers

    private static String buildName(Contact c, Date d) {
        String fullName = (String.isBlank(c.FirstName) ? '' : c.FirstName.trim() + ' ')
            + c.LastName;
        String dateStr = String.valueOf(d.year()).leftPad(4, '0') + '-'
            + String.valueOf(d.month()).leftPad(2, '0') + '-'
            + String.valueOf(d.day()).leftPad(2, '0');
        return fullName + ' Donation ' + dateStr;
    }

    private static String getWonStage() {
        List<OpportunityStage> stages = [
            SELECT ApiName
            FROM OpportunityStage
            WHERE IsActive = true AND IsClosed = true AND IsWon = true
            ORDER BY SortOrder
        ];
        if (stages.isEmpty()) {
            return DEFAULT_WON_STAGE;
        }
        for (OpportunityStage s : stages) {
            if (s.ApiName == DEFAULT_WON_STAGE) {
                return s.ApiName;
            }
        }
        return stages[0].ApiName;
    }

    /**
     * Ensures exactly one contact role per household contact.
     * The donor gets Donor and is primary; everyone else gets Household Member.
     * Roles NPSP already created are reused, corrected if needed, and de-duplicated.
     */
    private static void reconcileContactRoles(Id oppId, Id donorId, Id householdId) {
        Set<Id> householdContactIds = new Set<Id>{ donorId };
        for (Contact member : [SELECT Id FROM Contact WHERE AccountId = :householdId]) {
            householdContactIds.add(member.Id);
        }

        Map<Id, List<OpportunityContactRole>> rolesByContact =
            new Map<Id, List<OpportunityContactRole>>();
        for (OpportunityContactRole ocr : [
            SELECT Id, ContactId, Role, IsPrimary
            FROM OpportunityContactRole
            WHERE OpportunityId = :oppId
            ORDER BY CreatedDate, Id
        ]) {
            if (!rolesByContact.containsKey(ocr.ContactId)) {
                rolesByContact.put(ocr.ContactId, new List<OpportunityContactRole>());
            }
            rolesByContact.get(ocr.ContactId).add(ocr);
        }

        List<OpportunityContactRole> toDelete = new List<OpportunityContactRole>();
        List<OpportunityContactRole> toUpdate = new List<OpportunityContactRole>();
        List<OpportunityContactRole> toInsert = new List<OpportunityContactRole>();

        // Any contact (in or out of the household) must hold at most one role.
        for (Id cId : rolesByContact.keySet()) {
            List<OpportunityContactRole> roles = rolesByContact.get(cId);
            for (Integer i = 1; i < roles.size(); i++) {
                toDelete.add(roles[i]);
            }
        }

        for (Id cId : householdContactIds) {
            Boolean isDonor = (cId == donorId);
            String wantedRole = isDonor ? DONOR_ROLE : HOUSEHOLD_MEMBER_ROLE;

            if (rolesByContact.containsKey(cId)) {
                OpportunityContactRole keep = rolesByContact.get(cId)[0];
                Boolean changed = false;
                if (keep.Role != wantedRole) {
                    keep.Role = wantedRole;
                    changed = true;
                }
                if (keep.IsPrimary != isDonor) {
                    keep.IsPrimary = isDonor;
                    changed = true;
                }
                if (changed) {
                    toUpdate.add(keep);
                }
            } else {
                toInsert.add(new OpportunityContactRole(
                    OpportunityId = oppId,
                    ContactId = cId,
                    Role = wantedRole,
                    IsPrimary = isDonor
                ));
            }
        }

        if (!toDelete.isEmpty()) {
            delete toDelete;
        }
        if (!toUpdate.isEmpty()) {
            update toUpdate;
        }
        if (!toInsert.isEmpty()) {
            insert toInsert;
        }
    }

    /**
     * Ensures exactly one payment: paid, full amount, dated giftDate.
     * Reuses a payment NPSP auto-created, if any, and removes extras.
     */
    private static void reconcilePayment(Id oppId, Decimal amount, Date giftDate) {
        List<npe01__OppPayment__c> payments = [
            SELECT Id, npe01__Payment_Amount__c, npe01__Payment_Date__c,
                   npe01__Scheduled_Date__c, npe01__Paid__c
            FROM npe01__OppPayment__c
            WHERE npe01__Opportunity__c = :oppId
            ORDER BY CreatedDate, Id
        ];

        if (payments.isEmpty()) {
            insert new npe01__OppPayment__c(
                npe01__Opportunity__c = oppId,
                npe01__Payment_Amount__c = amount,
                npe01__Payment_Date__c = giftDate,
                npe01__Scheduled_Date__c = giftDate,
                npe01__Paid__c = true
            );
            return;
        }

        // Delete extras first so NPSP payment-total validation never sees an overage.
        if (payments.size() > 1) {
            List<npe01__OppPayment__c> extras = new List<npe01__OppPayment__c>();
            for (Integer i = 1; i < payments.size(); i++) {
                extras.add(payments[i]);
            }
            delete extras;
        }

        npe01__OppPayment__c p = payments[0];
        if (p.npe01__Payment_Amount__c != amount
                || p.npe01__Payment_Date__c != giftDate
                || p.npe01__Scheduled_Date__c != giftDate
                || p.npe01__Paid__c != true) {
            p.npe01__Payment_Amount__c = amount;
            p.npe01__Payment_Date__c = giftDate;
            p.npe01__Scheduled_Date__c = giftDate;
            p.npe01__Paid__c = true;
            update p;
        }
    }
}
```

**Design notes:**
- **Contact roles:** I don't set `Opportunity.ContactId`, so Salesforce adds no extra contact role of its own. After insert, the code reuses any role NPSP created, corrects its role and primary flag, deletes duplicates, and adds only what is missing. Any contact ends up with at most one role, even someone outside the household.
- **Payments:** NPSP may auto-create a payment for a Closed Won gift. If one exists, the code updates it to the required values and deletes any extras first. If none exists, it creates one. The gift always ends with exactly one paid payment for the full amount on `giftDate`.
- **Stage:** The stage is the org's active won stage, preferring `Closed Won`. The date in the name is built manually as `yyyy-MM-dd`, so time zones and locale can't change it.
- **Validation:** It throws `IllegalArgumentException` for a missing or nonexistent contact and for a null, zero or negative amount. I made two assumptions beyond the task: a null `giftDate` also throws, and so does a contact with no household account.
- **Rollback:** Everything runs under a savepoint, so a failure partway through leaves no partial gift.
- **Sharing:** The class is `with sharing`, so it respects the running volunteer user's record access.

