/**
 * Links child Contacts to parent Contacts using NPSP Relationships.
 *
 * With NPSP's default "List Setting" reciprocal method, one relationship is inserted
 * per pair:
 *   npe4__Contact__c        = child  (the record whose related list shows it)
 *   npe4__RelatedContact__c = parent
 *   npe4__Type__c           = 'Parent' (what the related contact is to the contact)
 *
 * NPSP's relationship trigger then creates the reciprocal record automatically:
 *   Contact = parent, RelatedContact = child, Type = Son / Daughter / Child
 *   (from the 'Parent' Relationship Lookup and the child's gender), and links both
 *   via npe4__ReciprocalRelationship__c.
 * The reciprocal is not inserted here, because NPSP would then create reciprocals
 * of the reciprocals and produce duplicate records.
 */
public with sharing class FamilyService {

    private static final String TYPE_PARENT = 'Parent';
    private static final String STATUS_CURRENT = 'Current';

    public static void linkParents(Map<Id, Id> parentIdByChildId) {
        if (parentIdByChildId == null || parentIdByChildId.isEmpty()) {
            return;
        }

        // Collect every contact involved in a valid pair
        Set<Id> contactIds = new Set<Id>();
        for (Id childId : parentIdByChildId.keySet()) {
            Id parentId = parentIdByChildId.get(childId);
            if (childId == null || parentId == null || childId == parentId) {
                continue;
            }
            contactIds.add(childId);
            contactIds.add(parentId);
        }
        if (contactIds.isEmpty()) {
            return;
        }

        // Single query: find existing relationships between any two of these contacts.
        // Store an order-independent key so that either direction counts as existing.
        Set<String> linkedPairs = new Set<String>();
        for (npe4__Relationship__c rel : [
            SELECT npe4__Contact__c, npe4__RelatedContact__c
            FROM npe4__Relationship__c
            WHERE npe4__Contact__c IN :contactIds
              AND npe4__RelatedContact__c IN :contactIds
            WITH USER_MODE
        ]) {
            linkedPairs.add(pairKey(rel.npe4__Contact__c, rel.npe4__RelatedContact__c));
        }

        List<npe4__Relationship__c> toInsert = new List<npe4__Relationship__c>();
        for (Id childId : parentIdByChildId.keySet()) {
            Id parentId = parentIdByChildId.get(childId);
            if (childId == null || parentId == null || childId == parentId) {
                continue;
            }
            String key = pairKey(childId, parentId);
            if (linkedPairs.contains(key)) {
                // Already related (either direction), or already queued in this call
                continue;
            }
            linkedPairs.add(key);

            toInsert.add(new npe4__Relationship__c(
                npe4__Contact__c = childId,
                npe4__RelatedContact__c = parentId,
                npe4__Type__c = TYPE_PARENT,
                npe4__Status__c = STATUS_CURRENT
            ));
        }

        if (!toInsert.isEmpty()) {
            // Single DML; NPSP creates and links the reciprocal records
            Database.insert(toInsert, true, AccessLevel.USER_MODE);
        }
    }

    /** Order-independent key for a pair of contact Ids (15/18-char safe). */
    private static String pairKey(Id a, Id b) {
        String sa = String.valueOf(a).left(15);
        String sb = String.valueOf(b).left(15);
        return sa < sb ? sa + ':' + sb : sb + ':' + sa;
    }
}
```

**Notes:**
- **Duplicate checks:** The single query finds any existing relationship between the involved contacts, in either direction. This makes re-runs safe. The same check also skips a second pair that would link two contacts already queued in the same call (for example, A→B and B→A).
- **Invalid pairs:** Pairs with a null child, a null parent, or the same contact on both sides are skipped.
- **Query and DML limits:** The class uses one SOQL query and one DML statement however many pairs are passed.
- **Security:** The query and insert run in user mode under `with sharing`, so object, field and sharing permissions are enforced. The import user needs access to Relationship records.
- **Hidden records:** If sharing hides an existing relationship from that user, the class cannot see it and could create a duplicate.

