/**
 * NPSP TDTM trigger handler that creates a follow-up Task when an Opportunity
 * becomes a qualifying major gift. A gift qualifies when it is Closed Won and
 * its Amount is at least 5,000.
 *
 * There is deliberately no Apex trigger for this class. NPSP's TDTM dispatcher
 * creates it by name from its Trigger Handler record:
 *   Class          = OPP_MajorGiftFollowUp_TDTM
 *   Object         = Opportunity
 *   Trigger Action = AfterInsert;AfterUpdate
 *   Load Order     = 5
 *   Asynchronous   = false
 * Deactivating that Trigger Handler record stops this handler from running.
 *
 * The class and its run method must be global. The NPSP managed package
 * creates the handler from outside this namespace, so it needs global access.
 *
 * Governor usage: the handler runs no SOQL. All needed fields (IsWon, Amount,
 * CloseDate, OwnerId, npsp__Primary_Contact__c) are already on the trigger
 * records. It runs no DML of its own either. The Tasks go back to NPSP in the
 * DmlWrapper, and NPSP inserts them in one bulk statement at the end of the
 * trigger dispatch.
 */
global with sharing class OPP_MajorGiftFollowUp_TDTM extends npsp.TDTM_Runnable {

    @TestVisible private static final Decimal MAJOR_GIFT_THRESHOLD = 5000;
    @TestVisible private static final String TASK_SUBJECT = 'Major gift thank-you call';
    @TestVisible private static final String TASK_PRIORITY = 'High';
    @TestVisible private static final String TASK_STATUS = 'Not Started';
    @TestVisible private static final Integer FOLLOW_UP_DAYS = 3;

    global override npsp.TDTM_Runnable.DmlWrapper run(
        List<SObject> newlist,
        List<SObject> oldlist,
        npsp.TDTM_Runnable.Action triggerAction,
        Schema.DescribeSObjectResult objResult
    ) {
        npsp.TDTM_Runnable.DmlWrapper dmlWrapper = new npsp.TDTM_Runnable.DmlWrapper();

        if (newlist == null || newlist.isEmpty()) {
            return dmlWrapper;
        }

        Boolean isInsert = triggerAction == npsp.TDTM_Runnable.Action.AfterInsert;
        Boolean isUpdate = triggerAction == npsp.TDTM_Runnable.Action.AfterUpdate;
        if (!isInsert && !isUpdate) {
            return dmlWrapper;
        }

        // Map old values by Id so the result does not depend on list order.
        Map<Id, Opportunity> oldById = new Map<Id, Opportunity>();
        if (isUpdate && oldlist != null) {
            for (SObject so : oldlist) {
                oldById.put((Id) so.get('Id'), (Opportunity) so);
            }
        }

        List<Task> tasksToInsert = new List<Task>();

        for (SObject so : newlist) {
            Opportunity opp = (Opportunity) so;

            if (!isMajorGift(opp)) {
                continue;
            }

            if (isUpdate) {
                Opportunity oldOpp = oldById.get(opp.Id);
                // If the gift already qualified before this update, skip it so
                // no duplicate Task is created.
                if (oldOpp != null && isMajorGift(oldOpp)) {
                    continue;
                }
            }

            tasksToInsert.add(buildTask(opp));
        }

        if (!tasksToInsert.isEmpty()) {
            dmlWrapper.objectsToInsert.addAll((List<SObject>) tasksToInsert);
        }

        return dmlWrapper;
    }

    /**
     * Returns true when the Opportunity is Closed Won and Amount >= threshold.
     * IsWon comes from the stage and is set on records in after triggers.
     */
    @TestVisible
    private static Boolean isMajorGift(Opportunity opp) {
        return opp != null
            && opp.IsWon == true
            && opp.Amount != null
            && opp.Amount >= MAJOR_GIFT_THRESHOLD;
    }

    @TestVisible
    private static Task buildTask(Opportunity opp) {
        return new Task(
            Subject = TASK_SUBJECT,
            Priority = TASK_PRIORITY,
            Status = TASK_STATUS,
            WhatId = opp.Id,
            WhoId = opp.npsp__Primary_Contact__c, // may be null
            OwnerId = opp.OwnerId,
            ActivityDate = opp.CloseDate == null ? null : opp.CloseDate.addDays(FOLLOW_UP_DAYS)
        );
    }
}
```

**Notes:**
- Closed Won is detected with `IsWon` rather than a hard-coded stage name. So it keeps working if the nonprofit renames or adds won stages.
- The Tasks are returned to NPSP in the `DmlWrapper` rather than inserted directly. NPSP then inserts them in one bulk statement, which keeps the handler's own SOQL and DML at zero.

## Explanation of each setting

1. **Default directory and automatic build numbers.** `triage` has `"default": true`. Setting `"versionNumber": "1.2.0.NEXT"` makes each `sf package version create` take the next build number on its own.

2. **Ancestor tracks the highest promoted version.** `"ancestorVersion": "HIGHEST"` sets the ancestor to the highest promoted version at the time each version is created. Today that is 1.1. After 1.2 is promoted, the next version's ancestor becomes 1.2. Nobody needs to edit the file after a release.

3. **Test fixtures stay out of the package.** `"unpackagedMetadata": { "path": "triage-test-fixtures" }` deploys that directory's metadata only to the build org. There it supports the Apex tests that run with `--code-coverage`. The metadata is never added to the package version and never installed in subscriber orgs.

4. **Test user access.** `apexTestAccess` assigns two things to the user that runs the package-build Apex tests:
   - the packaged permission set `Triage_Agent` (in `permissionSets`), and
   - the permission set license `SalesConsoleUser` (in `permissionSetLicenses`).

   Because the package has a namespace, Salesforce may require the namespaced name `triagex__Triage_Agent` for a permission set that is part of the package. If version creation reports that it can't find `Triage_Agent`, use the namespaced form.

5. **Fixtures available to developers.** `triage-test-fixtures` is also listed as its own package directory with `"default": false` and no `package` key. That lets `sf project deploy start` push it to scratch orgs while it belongs to no package. This is the pattern Salesforce documents for unpackaged metadata.

6. **API version, namespace and alias.**
   - `sourceApiVersion` is `"65.0"`.
   - `namespace` is `triagex`.
   - `packageAliases` maps the package name to its ID `0Ho8d000000XyZ7CAK`.

