/**
 * Trigger action (Trigger Actions Framework) for Account, After Insert.
 *
 * Creates an onboarding Task for the owner of every newly created Account whose
 * Type is 'Customer - Direct' or 'Customer - Channel'.
 *
 * Bulk-safe: all Tasks are inserted with a single DML statement per trigger
 * execution, and no DML is performed when no Account qualifies.
 */
public inherited sharing class TA_Account_CreateOnboardingTask implements TriggerAction.AfterInsert {
    @TestVisible
    private static final Set<String> CUSTOMER_TYPES = new Set<String>{
        'Customer - Direct',
        'Customer - Channel'
    };

    @TestVisible
    private static final String TASK_SUBJECT = 'Onboard new customer';
    @TestVisible
    private static final String TASK_STATUS = 'Not Started';
    @TestVisible
    private static final String TASK_PRIORITY = 'Normal';
    @TestVisible
    private static final Integer DAYS_UNTIL_DUE = 7;

    public void afterInsert(List<SObject> triggerNew) {
        if (triggerNew == null || triggerNew.isEmpty()) {
            return;
        }

        Date dueDate = Date.today().addDays(DAYS_UNTIL_DUE);
        List<Task> tasksToInsert = new List<Task>();

        for (Account acc : (List<Account>) triggerNew) {
            if (acc.Type != null && CUSTOMER_TYPES.contains(acc.Type)) {
                tasksToInsert.add(
                    new Task(
                        Subject = TASK_SUBJECT,
                        WhatId = acc.Id,
                        OwnerId = acc.OwnerId,
                        ActivityDate = dueDate,
                        Status = TASK_STATUS,
                        Priority = TASK_PRIORITY
                    )
                );
            }
        }

        if (tasksToInsert.isEmpty()) {
            return;
        }

        insert tasksToInsert;
    }
}
```

