/**
 * DML-less, SOQL-less unit tests for TA_Opportunity_GuardAmountDecrease.
 *
 * Fake Ids are generated locally (same algorithm as TAF's TriggerTestUtility.getFakeId):
 * @IsTest classes inside a 2GP (unlocked) package are not accessible to code outside
 * the package, so TriggerTestUtility cannot be referenced from org code.
 */
@IsTest
private class TA_Opportunity_GuardAmountDecreaseTest {
    private static Integer fakeIdCounter = 1;

    private static Id fakeId() {
        String prefix = Opportunity.SObjectType.getDescribe().getKeyPrefix();
        String suffix = String.valueOf(fakeIdCounter++).leftPad(12, '0');
        return Id.valueOf(prefix + suffix);
    }

    private static TA_Opportunity_GuardAmountDecrease action = new TA_Opportunity_GuardAmountDecrease();

    /** Runs the action for a single old/new Amount pair and returns the new record. */
    private static Opportunity runSingle(Decimal oldAmount, Decimal newAmount) {
        Id oppId = fakeId();
        Opportunity oldOpp = new Opportunity(Id = oppId, Name = 'Test', Amount = oldAmount);
        Opportunity newOpp = new Opportunity(Id = oppId, Name = 'Test', Amount = newAmount);
        action.beforeUpdate(new List<Opportunity>{ newOpp }, new List<Opportunity>{ oldOpp });
        return newOpp;
    }

    private static void assertSingleGuardError(Opportunity opp) {
        Assert.isTrue(opp.hasErrors(), 'Record should have an error');
        List<Database.Error> errors = opp.getErrors();
        Assert.areEqual(1, errors.size(), 'Exactly one error expected');
        Assert.areEqual(
            TA_Opportunity_GuardAmountDecrease.ERROR_MESSAGE,
            errors[0].getMessage(),
            'Unexpected error message'
        );
    }

    private static void assertNoErrors(Opportunity opp) {
        Assert.isFalse(opp.hasErrors(), 'Record should not have errors: ' + opp.getErrors());
        Assert.areEqual(0, opp.getErrors().size(), 'No errors expected');
    }

    @IsTest
    static void reductionOfMoreThanHalfIsRejected() {
        Opportunity result = runSingle(1000, 499);
        assertSingleGuardError(result);
    }

    @IsTest
    static void reductionOfExactlyHalfIsAccepted() {
        Opportunity result = runSingle(1000, 500);
        assertNoErrors(result);
    }

    @IsTest
    static void increaseIsAccepted() {
        Opportunity result = runSingle(1000, 5000);
        assertNoErrors(result);
    }

    @IsTest
    static void nullPreviousAmountIsAcceptedWithoutException() {
        Opportunity result;
        try {
            result = runSingle(null, 10);
        } catch (Exception e) {
            Assert.fail('No exception expected for null previous Amount: ' + e.getMessage());
        }
        assertNoErrors(result);
    }

    @IsTest
    static void mixedBatchFlagsOnlyViolatingRecords() {
        List<Decimal> oldAmounts = new List<Decimal>{ 1000, 1000, 1000, null, 200, 2000 };
        List<Decimal> newAmounts = new List<Decimal>{ 499, 500, 1500, 10, 50, 999.99 };
        List<Boolean> expectError = new List<Boolean>{ true, false, false, false, true, true };

        List<Opportunity> triggerNew = new List<Opportunity>();
        List<Opportunity> triggerOld = new List<Opportunity>();
        for (Integer i = 0; i < oldAmounts.size(); i++) {
            Id oppId = fakeId();
            triggerOld.add(new Opportunity(Id = oppId, Name = 'Opp ' + i, Amount = oldAmounts[i]));
            triggerNew.add(new Opportunity(Id = oppId, Name = 'Opp ' + i, Amount = newAmounts[i]));
        }
        // Reverse old list order to prove matching is by Id, not position
        List<Opportunity> reversedOld = new List<Opportunity>();
        for (Integer i = triggerOld.size() - 1; i >= 0; i--) {
            reversedOld.add(triggerOld[i]);
        }

        action.beforeUpdate(triggerNew, reversedOld);

        for (Integer i = 0; i < triggerNew.size(); i++) {
            if (expectError[i]) {
                assertSingleGuardError(triggerNew[i]);
            } else {
                assertNoErrors(triggerNew[i]);
            }
        }
    }
}
