/**
 * Trigger action (Trigger Actions Framework) that prevents two Contacts of the same
 * Account from sharing an email address (compared case-insensitively).
 *
 * Contacts without an Account or without an Email are not checked.
 * On update, only contacts whose Email or AccountId changed are checked, so legacy
 * duplicates do not block unrelated edits. A contact never conflicts with itself.
 * Within one save, the first contact for an Account/Email pair is accepted and each
 * later one is rejected.
 *
 * Bulk-safe: at most one SOQL query per execution.
 *
 * Declared "without sharing" on purpose: this is a data-integrity rule, so it must see
 * every Contact on the Account, including ones the running user cannot see.
 */
public without sharing class TA_Contact_PreventDuplicateEmail implements TriggerAction.BeforeInsert, TriggerAction.BeforeUpdate {
    @TestVisible
    private static final String ERROR_MESSAGE = 'Another contact on this account already uses this email address.';

    public void beforeInsert(List<SObject> triggerNew) {
        validate(triggerNew, null);
    }

    public void beforeUpdate(List<SObject> triggerNew, List<SObject> triggerOld) {
        validate(triggerNew, new Map<Id, SObject>(triggerOld));
    }

    private void validate(List<SObject> triggerNew, Map<Id, SObject> oldMap) {
        // Contacts that must be checked, in trigger order
        List<Contact> candidates = new List<Contact>();
        // Account/Email keys already held by contacts in this save that are NOT checked
        // (unchanged contacts in an update); they keep their values after the save.
        Set<String> occupiedKeys = new Set<String>();
        Set<Id> batchIds = new Set<Id>();
        Set<Id> accountIds = new Set<Id>();
        Set<String> emails = new Set<String>();

        for (SObject record : triggerNew) {
            Contact newContact = (Contact) record;
            if (newContact.Id != null) {
                batchIds.add(newContact.Id);
            }
            if (!isCheckable(newContact)) {
                continue;
            }
            Boolean mustCheck = true;
            if (oldMap != null) {
                Contact oldContact = (Contact) oldMap.get(newContact.Id);
                // Apex String comparison is case-insensitive, so a case-only change of
                // the email is not considered a change (consistent with the rule).
                mustCheck = oldContact == null ||
                    newContact.Email != oldContact.Email ||
                    newContact.AccountId != oldContact.AccountId;
            }
            if (mustCheck) {
                candidates.add(newContact);
                accountIds.add(newContact.AccountId);
                emails.add(newContact.Email.trim().toLowerCase());
            } else {
                occupiedKeys.add(buildKey(newContact.AccountId, newContact.Email));
            }
        }

        if (candidates.isEmpty()) {
            return;
        }

        // Single query. Contacts in this save are excluded: their in-memory values are
        // authoritative (and a contact must never conflict with itself).
        // String IN comparison in SOQL is case-insensitive.
        for (Contact existing : [
            SELECT Id, AccountId, Email
            FROM Contact
            WHERE AccountId IN :accountIds AND Email IN :emails AND Id NOT IN :batchIds
        ]) {
            if (existing.AccountId != null && String.isNotBlank(existing.Email)) {
                occupiedKeys.add(buildKey(existing.AccountId, existing.Email));
            }
        }

        for (Contact candidate : candidates) {
            String key = buildKey(candidate.AccountId, candidate.Email);
            if (occupiedKeys.contains(key)) {
                candidate.addError(ERROR_MESSAGE);
            } else {
                // First one in the list wins; later ones in the same save are rejected
                occupiedKeys.add(key);
            }
        }
    }

    private static Boolean isCheckable(Contact c) {
        return c.AccountId != null && String.isNotBlank(c.Email);
    }

    private static String buildKey(Id accountId, String email) {
        // Id.toString() always yields the 18-character form
        return String.valueOf(accountId) + '|' + email.trim().toLowerCase();
    }
}
