/**
 * Trigger action that normalizes contact information on Leads before they are first saved.
 *
 * - Email: trimmed and lower-cased (null stays null; whitespace-only becomes null).
 * - Company: trimmed.
 * - LeadSource: defaults to 'Web' when blank.
 *
 * Runs in the before insert context, so changes go straight into the original save.
 * It uses no SOQL and no DML and is bulk safe.
 */
public inherited sharing class TA_Lead_NormalizeContactInfo implements TriggerAction.BeforeInsert {
    @TestVisible
    private static final String DEFAULT_LEAD_SOURCE = 'Web';

    public void beforeInsert(List<SObject> triggerNew) {
        for (Lead record : (List<Lead>) triggerNew) {
            normalize(record);
        }
    }

    private static void normalize(Lead record) {
        if (record.Email != null) {
            String cleanedEmail = record.Email.trim().toLowerCase();
            record.Email = String.isBlank(cleanedEmail) ? null : cleanedEmail;
        }

        if (record.Company != null) {
            record.Company = record.Company.trim();
        }

        if (String.isBlank(record.LeadSource)) {
            record.LeadSource = DEFAULT_LEAD_SOURCE;
        }
    }
}
