File: force-app/main/default/classes/TA_Case_RollupOpenCount.cls
```apex
/**
 * Trigger action (Trigger Actions Framework) that keeps Account.FB_Open_Case_Count__c
 * equal to the number of the account's Cases with IsClosed = false.
 *
 * Registered in after insert, after update, after delete and after undelete on Case.
 *
 * Approach: collect the affected Account Ids (old and new), lock those accounts,
 * recount their open cases with one aggregate query and update only accounts
 * whose stored value differs. Accounts with no open cases get 0, not null.
 * Uses at most 2 SOQL queries and 1 DML statement per execution.
 *
 * The class runs without sharing on purpose. The roll-up must count every case on
 * the account, not only the cases the running user can see. A user who can edit a
 * case may also have no edit access to its account.
 */
public without sharing class TA_Case_RollupOpenCount implements TriggerAction.AfterInsert, TriggerAction.AfterUpdate, TriggerAction.AfterDelete, TriggerAction.AfterUndelete {

    public void afterInsert(List<SObject> triggerNew) {
        recalculate(collectAccountIds((List<Case>) triggerNew));
    }

    public void afterUpdate(List<SObject> triggerNew, List<SObject> triggerOld) {
        Map<Id, Case> oldMap = new Map<Id, Case>((List<Case>) triggerOld);
        Set<Id> accountIds = new Set<Id>();
        for (Case newCase : (List<Case>) triggerNew) {
            Case oldCase = oldMap.get(newCase.Id);
            if (oldCase == null) {
                continue;
            }
            Boolean relevantChange =
                newCase.AccountId != oldCase.AccountId ||
                newCase.IsClosed != oldCase.IsClosed ||
                newCase.Status != oldCase.Status;
            if (!relevantChange) {
                continue;
            }
            if (newCase.AccountId != null) {
                accountIds.add(newCase.AccountId);
            }
            if (oldCase.AccountId != null) {
                accountIds.add(oldCase.AccountId);
            }
        }
        recalculate(accountIds);
    }

    public void afterDelete(List<SObject> triggerOld) {
        recalculate(collectAccountIds((List<Case>) triggerOld));
    }

    public void afterUndelete(List<SObject> triggerNew) {
        recalculate(collectAccountIds((List<Case>) triggerNew));
    }

    private static Set<Id> collectAccountIds(List<Case> cases) {
        Set<Id> accountIds = new Set<Id>();
        for (Case c : cases) {
            if (c.AccountId != null) {
                accountIds.add(c.AccountId);
            }
        }
        return accountIds;
    }

    private static void recalculate(Set<Id> accountIds) {
        if (accountIds == null || accountIds.isEmpty()) {
            return;
        }

        // SOQL 1: lock the affected accounts so concurrent transactions recount in sequence.
        // Accounts that no longer exist are simply not returned.
        List<Account> accounts = [
            SELECT Id, FB_Open_Case_Count__c
            FROM Account
            WHERE Id IN :accountIds
            FOR UPDATE
        ];
        if (accounts.isEmpty()) {
            return;
        }

        // SOQL 2: recount open cases. Deleted cases are excluded automatically;
        // undeleted cases are counted again.
        Map<Id, Integer> openCountByAccount = new Map<Id, Integer>();
        for (AggregateResult ar : [
            SELECT AccountId accId, COUNT(Id) openCount
            FROM Case
            WHERE AccountId IN :accountIds AND IsClosed = false
            GROUP BY AccountId
        ]) {
            openCountByAccount.put((Id) ar.get('accId'), (Integer) ar.get('openCount'));
        }

        List<Account> accountsToUpdate = new List<Account>();
        for (Account acc : accounts) {
            Integer openCount = openCountByAccount.containsKey(acc.Id)
                ? openCountByAccount.get(acc.Id)
                : 0;
            if (acc.FB_Open_Case_Count__c == null || acc.FB_Open_Case_Count__c != openCount) {
                accountsToUpdate.add(new Account(Id = acc.Id, FB_Open_Case_Count__c = openCount));
            }
        }

        // DML 1
        if (!accountsToUpdate.isEmpty()) {
            update accountsToUpdate;
        }
    }
}
```

