/**
 * Shared, cached queries for Contact trigger actions (Trigger Actions Framework
 * "avoid repeated queries" pattern).
 *
 * The inner Service class is registered as the first before-insert action and
 * (re)loads the parent accounts once per trigger execution. Subsequent actions
 * read them through TA_Contact_Queries.getInstance().accountsById.
 */
public with sharing class TA_Contact_Queries {
    private static TA_Contact_Queries instance;

    /** Parent accounts of the contacts in the current trigger execution. */
    public Map<Id, Account> accountsById = new Map<Id, Account>();

    private TA_Contact_Queries() {
    }

    public static TA_Contact_Queries getInstance() {
        if (TA_Contact_Queries.instance == null) {
            TA_Contact_Queries.instance = new TA_Contact_Queries();
        }
        return TA_Contact_Queries.instance;
    }

    /**
     * Trigger action that loads the parent accounts. Runs first in before insert
     * and reloads the map on every trigger execution.
     */
    public with sharing class Service implements TriggerAction.BeforeInsert {
        public void beforeInsert(List<SObject> triggerNew) {
            TA_Contact_Queries.getInstance().accountsById = loadAccounts((List<Contact>) triggerNew);
        }

        private Map<Id, Account> loadAccounts(List<Contact> contacts) {
            Set<Id> accountIds = new Set<Id>();
            for (Contact c : contacts) {
                if (c.AccountId != null) {
                    accountIds.add(c.AccountId);
                }
            }
            if (accountIds.isEmpty()) {
                return new Map<Id, Account>();
            }
            return new Map<Id, Account>(
                [
                    SELECT Id, BillingStreet, BillingCity, BillingPostalCode, BillingCountry, AccountSource
                    FROM Account
                    WHERE Id IN :accountIds
                ]
            );
        }
    }
}
