/**
 * Before insert: when a new contact has an Account and its mailing address is
 * completely blank (street, city, postal code and country), copy the account's
 * billing address into it. Contacts with any mailing field filled keep their own.
 * Uses the accounts loaded by TA_Contact_Queries.Service (no queries here).
 */
public inherited sharing class TA_Contact_InheritMailingAddress implements TriggerAction.BeforeInsert {
    public void beforeInsert(List<SObject> triggerNew) {
        Map<Id, Account> accountsById = TA_Contact_Queries.getInstance().accountsById;
        if (accountsById == null || accountsById.isEmpty()) {
            return;
        }
        for (Contact c : (List<Contact>) triggerNew) {
            if (c.AccountId == null || !isMailingAddressBlank(c)) {
                continue;
            }
            Account acc = accountsById.get(c.AccountId);
            if (acc == null) {
                continue;
            }
            c.MailingStreet = acc.BillingStreet;
            c.MailingCity = acc.BillingCity;
            c.MailingPostalCode = acc.BillingPostalCode;
            c.MailingCountry = acc.BillingCountry;
        }
    }

    private static Boolean isMailingAddressBlank(Contact c) {
        return String.isBlank(c.MailingStreet) &&
            String.isBlank(c.MailingCity) &&
            String.isBlank(c.MailingPostalCode) &&
            String.isBlank(c.MailingCountry);
    }
}
