/**
 * Before insert: when a new contact has an Account and a blank LeadSource,
 * default LeadSource to the account's AccountSource.
 * Uses the accounts loaded by TA_Contact_Queries.Service (no queries here).
 */
public inherited sharing class TA_Contact_DefaultLeadSource implements TriggerAction.BeforeInsert {
    public void beforeInsert(List<SObject> triggerNew) {
        Map<Id, Account> accountsById = TA_Contact_Queries.getInstance().accountsById;
        if (accountsById == null || accountsById.isEmpty()) {
            return;
        }
        for (Contact c : (List<Contact>) triggerNew) {
            if (c.AccountId == null || String.isNotBlank(c.LeadSource)) {
                continue;
            }
            Account acc = accountsById.get(c.AccountId);
            if (acc == null) {
                continue;
            }
            c.LeadSource = acc.AccountSource;
        }
    }
}
